import type { ExerciseQuestion } from "../types";

export const CONDITIONAL_QUESTIONS: ExerciseQuestion[] = [
  { id: "c001", question: "If you heat water to 100°C, it _____.", options: ["boil", "boils", "will boil", "would boil"], correctIndex: 1, explanation: "Đây là câu điều kiện loại 0 diễn tả một sự thật khoa học luôn đúng, với công thức 'If + thì hiện tại đơn, + thì hiện tại đơn'. Vì đun nước tới 100°C thì nước luôn sôi bất kể thời điểm nào, nên cả hai mệnh đề đều chia ở hiện tại đơn, do đó 'boils' (chia theo 'it') là đáp án đúng. Đừng chọn 'will boil' hay 'would boil' vì đó là công thức của câu điều kiện loại 1 và loại 2, chỉ dùng khi nói về khả năng hoặc giả định, không phải quy luật tự nhiên." },
  { id: "c002", question: "If you _____ this button, the alarm goes off.", options: ["press", "pressed", "will press", "would press"], correctIndex: 0, explanation: "Câu điều kiện loại 0 dùng để nói về kết quả tất yếu, luôn xảy ra: 'If + hiện tại đơn, + hiện tại đơn'. Bấm nút này thì chuông báo động luôn kêu, đây là quy luật máy móc chứ không phải một khả năng trong tương lai, nên mệnh đề 'if' phải chia hiện tại đơn 'press'. Tránh nhầm sang 'will press' - đó là cách chia sai, vì trong mệnh đề 'if' của cả loại 0 lẫn loại 1, ta không bao giờ dùng 'will'." },
  { id: "c003", question: "If plants _____ sunlight, they die.", options: ["don't get", "doesn't get", "won't get", "wouldn't get"], correctIndex: 0, explanation: "Đây vẫn là câu điều kiện loại 0 (sự thật hiển nhiên): If + hiện tại đơn, + hiện tại đơn, chỉ khác là mệnh đề điều kiện ở thể phủ định. Vì chủ ngữ 'plants' là số nhiều nên trợ động từ phải là 'don't', không phải 'doesn't' (chia cho số ít). Chú ý đừng chọn 'won't get' - 'won't' chỉ xuất hiện ở mệnh đề kết quả của loại 1, không dùng trong mệnh đề 'if' của loại 0." },
  { id: "c004", question: "Metals _____ when they are heated.", options: ["expand", "expands", "will expand", "would expand"], correctIndex: 0, explanation: "Câu điều kiện loại 0 diễn tả sự thật khoa học: If/When + hiện tại đơn, + hiện tại đơn. Kim loại giãn nở khi bị nung nóng là một quy luật vật lý luôn đúng, nên mệnh đề chính cũng phải chia hiện tại đơn 'expand' (metals là số nhiều, không thêm 's'). 'Will expand' nghe có vẻ hợp lý nhưng sai vì loại 0 không dùng 'will' để nói về quy luật chung, 'will' chỉ dùng cho dự đoán/quyết định ở loại 1." },
  { id: "c005", question: "If it _____ tomorrow, we'll cancel the picnic.", options: ["rains", "will rain", "rained", "would rain"], correctIndex: 0, explanation: "Đây là câu điều kiện loại 1, diễn tả một việc có khả năng xảy ra ở tương lai: If + hiện tại đơn, + will + V. 'Tomorrow' cho thấy đây là một khả năng thực tế trong tương lai gần, nên mệnh đề 'if' chia hiện tại đơn 'rains'. Nhiều người nhầm chọn 'will rain' vì thấy có chữ 'tomorrow', nhưng quy tắc là mệnh đề 'if' không bao giờ dùng 'will', 'will' chỉ nằm ở mệnh đề kết quả (we'll cancel)." },
  { id: "c006", question: "She _____ call you if she finds your number.", options: ["will", "would", "should", "shall"], correctIndex: 0, explanation: "Đây là câu điều kiện loại 1: If + hiện tại đơn (finds), + will + V. Vì việc tìm ra số điện thoại là một khả năng thực tế có thể xảy ra, mệnh đề kết quả phải dùng 'will' để diễn tả điều sẽ xảy ra nếu điều kiện đó đúng. 'Would' là bẫy hay gặp nhất vì nó thuộc câu điều kiện loại 2 (giả định không có thật), không phù hợp khi mệnh đề 'if' đã chia hiện tại đơn như ở đây." },
  { id: "c007", question: "If you _____ hard enough, you'll pass the exam.", options: ["study", "will study", "studied", "would study"], correctIndex: 0, explanation: "Câu điều kiện loại 1: If + hiện tại đơn, + will + V. Việc học chăm chỉ và thi đỗ là điều hoàn toàn có thể xảy ra trong tương lai nên mệnh đề 'if' phải chia hiện tại đơn 'study', còn 'will' đã nằm sẵn ở mệnh đề sau (you'll pass). Đây là lỗi rất phổ biến: học viên hay chọn 'will study' vì nghĩ câu nói về tương lai nên cả hai mệnh đề đều phải có 'will', nhưng mệnh đề 'if' không bao giờ chia 'will'." },
  { id: "c008", question: "We won't be late if we _____ now.", options: ["leave", "will leave", "left", "would leave"], correctIndex: 0, explanation: "Vẫn là câu điều kiện loại 1, chỉ khác thứ tự: mệnh đề kết quả (won't be late) đứng trước, mệnh đề 'if' đứng sau, nhưng công thức không đổi: if + hiện tại đơn. Ở đây việc rời đi ngay bây giờ là một hành động hoàn toàn khả thi nên dùng 'leave'. Đừng để vị trí câu đánh lừa mà chọn 'will leave' - dù mệnh đề 'if' đứng ở cuối câu, nó vẫn phải tuân theo quy tắc chia hiện tại đơn, không dùng 'will'." },
  { id: "c009", question: "Unless you _____ immediately, I'll call the police.", options: ["stop", "will stop", "stopped", "would stop"], correctIndex: 0, explanation: "'Unless' mang nghĩa phủ định, tương đương 'if...not', nên vế sau 'unless' vẫn theo công thức câu điều kiện loại 1: unless + hiện tại đơn, + will + V. Câu này nghĩa là 'Nếu bạn không dừng lại ngay, tôi sẽ gọi cảnh sát' - một tình huống thực tế có thể xảy ra ngay bây giờ. Vì 'unless' đã mang nghĩa phủ định sẵn nên không cần thêm 'not', và cũng không chia 'will stop' như ở mệnh đề chính." },
  { id: "c010", question: "What _____ you do if you miss the last bus?", options: ["do", "will", "would", "did"], correctIndex: 1, explanation: "Đây là câu hỏi ở câu điều kiện loại 1: What will + S + V if + hiện tại đơn? Vì lỡ chuyến xe buýt cuối là một tình huống thực tế có thể xảy ra, mệnh đề chính phải dùng 'will' để hỏi về phản ứng trong tương lai. Đừng nhầm với 'would' - đó là cách hỏi giả định của câu điều kiện loại 2, dùng khi tình huống chỉ là tưởng tượng chứ không thực tế như câu này." },
  { id: "c011", question: "If I _____ a million dollars, I'd travel the world.", options: ["have", "had", "will have", "would have"], correctIndex: 1, explanation: "Câu điều kiện loại 2 diễn tả một giả định trái với thực tế ở hiện tại: If + quá khứ đơn, + would + V. Câu này có nghĩa 'nếu tôi có một triệu đô' - một điều không có thật ở hiện tại (thực tế người nói không có số tiền đó), nên mệnh đề 'if' chia quá khứ đơn 'had'. Chú ý 'will have' là sai vì đó là cách chia của loại 1, chỉ dùng khi điều kiện có khả năng xảy ra thật, không phải một giả định xa vời như ở đây." },
  { id: "c012", question: "She would move to Paris if she _____ French.", options: ["speaks", "spoke", "will speak", "would speak"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn, + would + V. Vế chính đã có 'would move' báo hiệu đây là một giả định không có thật ở hiện tại (cô ấy hiện không biết tiếng Pháp), nên mệnh đề 'if' phải chia quá khứ đơn 'spoke'. Tránh chọn 'speaks' - đó là hiện tại đơn, chỉ phù hợp với loại 1 khi mệnh đề chính dùng 'will', không khớp với 'would' đã cho sẵn." },
  { id: "c013", question: "If he _____ taller, he could play basketball professionally.", options: ["is", "was", "were", "will be"], correctIndex: 2, explanation: "Câu điều kiện loại 2 với động từ 'to be' có một quy tắc riêng: dùng 'were' cho mọi ngôi (I, he, she, it...) chứ không phải 'was', đây là hình thức giả định (subjunctive) chuẩn mực trong văn viết. Câu nói về một điều trái thực tế - anh ấy không cao - nên phải dùng 'were taller'. 'Was' vẫn được chấp nhận trong văn nói thân mật, nhưng trong ngữ pháp chuẩn và các bài kiểm tra, 'were' luôn là đáp án đúng." },
  { id: "c014", question: "What _____ you do if you won the lottery?", options: ["do", "will", "would", "did"], correctIndex: 2, explanation: "Câu hỏi ở câu điều kiện loại 2: What would + S + V if + quá khứ đơn? Trúng số là một giả định khó xảy ra, hoàn toàn mang tính tưởng tượng, nên mệnh đề chính phải dùng 'would' thay vì 'will'. Nếu tình huống là khả năng thực tế (ví dụ 'if you win the match tomorrow'), ta mới dùng 'will' như ở loại 1; còn 'did' sai hoàn toàn vì đây không phải câu hỏi thông thường ở quá khứ." },
  { id: "c015", question: "If I _____ you, I wouldn't accept that offer.", options: ["am", "was", "were", "will be"], correctIndex: 2, explanation: "Cấu trúc quen thuộc 'If I were you' dùng để đưa ra lời khuyên, luôn chia 'were' chứ không phải 'was', dù chủ ngữ là 'I' - đây là điểm đặc biệt của câu điều kiện loại 2 với động từ to be. Người nói không thể thực sự 'là' người nghe nên đây là một giả định hoàn toàn phi thực tế. Ghi nhớ cụm 'If I were you' như một khối cố định để không bị nhầm sang 'was' hay 'am'." },
  { id: "c016", question: "I _____ more friends if I were more outgoing.", options: ["have", "had", "will have", "would have"], correctIndex: 3, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (were), + would + V. Vì mệnh đề 'if' đã chia 'were' (giả định không có thật ở hiện tại - người nói không hướng ngoại), mệnh đề kết quả phải dùng 'would have' để giữ tính nhất quán về thì. Đừng chọn 'will have' - trộn lẫn will với if-quá khứ là lỗi sai thì phổ biến giữa loại 1 và loại 2." },
  { id: "c017", question: "She _____ happier if she changed her job.", options: ["is", "was", "will be", "would be"], correctIndex: 3, explanation: "Câu điều kiện loại 2: mệnh đề 'if' đã chia quá khứ đơn (changed) nên mệnh đề kết quả bắt buộc phải là 'would + V nguyên thể', ở đây là 'would be'. Câu này diễn tả một giả định về hiện tại: nếu cô ấy đổi việc (nhưng hiện tại cô ấy chưa đổi) thì sẽ hạnh phúc hơn. 'Will be' là lựa chọn sai thường gặp vì học viên quên rằng khi 'if' đã dùng quá khứ đơn thì không thể có 'will' ở vế còn lại." },
  { id: "c018", question: "If it weren't raining, we _____ go for a walk.", options: ["can", "will", "would", "should"], correctIndex: 2, explanation: "Câu điều kiện loại 2: mệnh đề 'if' đã cho sẵn 'weren't' (quá khứ đơn phủ định của to be), nên mệnh đề kết quả phải dùng 'would + V' để tương ứng. Thực tế trời đang mưa nên đây là giả định trái ngược - nếu trời không mưa thì mới có thể đi dạo. 'Will' sai vì không khớp thì với 'weren't'; 'can/should' tuy nghe hợp lý về nghĩa nhưng không phải trợ động từ chuẩn của công thức câu điều kiện loại 2." },
  { id: "c019", question: "He wouldn't be so tired if he _____ to bed earlier.", options: ["go", "went", "will go", "has gone"], correctIndex: 1, explanation: "Câu điều kiện loại 2 ở thể phủ định vẫn giữ nguyên công thức: If + quá khứ đơn, + wouldn't + V. Vế chính 'wouldn't be' cho thấy đây là giả định trái thực tế ở hiện tại (thực tế anh ấy đã không đi ngủ sớm nên bây giờ đang mệt), nên mệnh đề 'if' phải chia 'went'. 'Has gone' dễ gây nhầm lẫn vì có vẻ giống quá khứ nhưng đó là thì hiện tại hoàn thành, không phải hình thức được dùng trong mệnh đề 'if' của loại 2." },
  { id: "c020", question: "I wish I _____ speak French fluently.", options: ["can", "could", "would", "shall"], correctIndex: 1, explanation: "Cấu trúc 'wish' + could + V dùng để ước ao về một khả năng không có ở hiện tại (giống tinh thần câu điều kiện loại 2: giả định trái thực tế). Người nói hiện không nói tiếng Pháp trôi chảy nên dùng 'could' để bày tỏ mong muốn có được khả năng đó. Đừng chọn 'can' - động từ theo sau 'wish' luôn phải lùi một thì so với hiện tại, đó là lý do 'can' (hiện tại) phải chuyển thành 'could' (quá khứ) khi đi sau 'wish'." },
  { id: "c021", question: "If she _____ harder, she would have passed the exam.", options: ["studied", "had studied", "would study", "has studied"], correctIndex: 1, explanation: "Câu điều kiện loại 3 dùng để giả định về một điều đã không xảy ra trong quá khứ: If + quá khứ hoàn thành (had + V3), + would have + V3. Cô ấy đã không học chăm và đã không đỗ, đây là một sự việc đã kết thúc trong quá khứ nên mệnh đề 'if' phải chia 'had studied'. 'Studied' (quá khứ đơn) là bẫy hay gặp vì gần giống về hình thức nhưng lại là công thức của loại 2 (giả định ở hiện tại), không phải loại 3." },
  { id: "c022", question: "We _____ the game if our best player hadn't been injured.", options: ["win", "won", "would win", "would have won"], correctIndex: 3, explanation: "Câu điều kiện loại 3: mệnh đề 'if' đã cho 'hadn't been injured' (quá khứ hoàn thành) nên mệnh đề kết quả phải là 'would have + V3', ở đây là 'would have won'. Câu diễn tả một kết quả không có thật trong quá khứ: cầu thủ giỏi nhất đã bị chấn thương nên đội đã thua. 'Would win' thiếu 'have' nên sai - đó là công thức của loại 2, không khớp với mệnh đề 'if' đã ở quá khứ hoàn thành." },
  { id: "c023", question: "If I had known, I _____ told you.", options: ["will have", "would have", "had", "could"], correctIndex: 1, explanation: "Câu điều kiện loại 3: If + had known (quá khứ hoàn thành), + would have + V3. Mệnh đề 'if' đã chia 'had known' cho thấy đây là việc đã rồi trong quá khứ (tôi đã không biết), nên vế kết quả phải là 'would have told'. 'Will have' sai về thì - 'will' không bao giờ xuất hiện trong câu điều kiện loại 3, chỉ 'would have' mới đúng khi kết hợp với 'had + V3' ở mệnh đề 'if'." },
  { id: "c024", question: "What would you have done if you _____ the interview?", options: ["don't pass", "didn't pass", "won't pass", "hadn't passed"], correctIndex: 3, explanation: "Câu hỏi ở câu điều kiện loại 3: What would you have done if + had + V3? Vế chính 'would you have done' đã báo hiệu đây là loại 3 nên mệnh đề 'if' bắt buộc phải chia quá khứ hoàn thành phủ định 'hadn't passed'. 'Didn't pass' (quá khứ đơn) là lựa chọn gây nhầm lẫn nhiều nhất vì nghe tự nhiên, nhưng nó chỉ đúng ở loại 2, không tương thích với 'would have done' ở đây." },
  { id: "c025", question: "He _____ ill if he'd worn a coat.", options: ["might not fall", "wouldn't have fallen", "won't fall", "didn't fall"], correctIndex: 1, explanation: "Chú ý 'he'd worn' ở đây là viết tắt của 'he had worn' (quá khứ hoàn thành) chứ không phải 'he would wear', nên đây là câu điều kiện loại 3: mệnh đề kết quả phải là 'wouldn't have + V3'. Câu nghĩa là: anh ấy đã bị ốm vì thực tế đã không mặc áo khoác. 'Might not fall' thiếu 'have' nên sai cấu trúc thì của loại 3, dù về nghĩa vẫn hợp lý." },
  { id: "c026", question: "If it _____ for your help, I'd have failed.", options: ["is not", "was not", "were not", "hadn't been"], correctIndex: 3, explanation: "Đây là cấu trúc cố định 'If it hadn't been for + danh từ', tương đương với 'Without + danh từ', dùng để nói 'nếu không nhờ có...' trong câu điều kiện loại 3. Vế sau 'I'd have failed' (would have failed) xác nhận đây là loại 3 nên mệnh đề 'if' phải ở quá khứ hoàn thành 'hadn't been'. 'Were not' dễ bị chọn nhầm vì giống văn phong trang trọng của loại 2, nhưng ở đây thì của vế chính đòi hỏi 'had' chứ không phải 'were'." },
  { id: "c027", question: "_____ I known about the meeting, I would have attended.", options: ["If", "Had", "Should", "Were"], correctIndex: 1, explanation: "Đây là câu điều kiện loại 3 ở dạng đảo ngữ trang trọng: đảo 'had' lên trước chủ ngữ và bỏ 'if' - 'Had I known' = 'If I had known'. Đảo ngữ này thường xuất hiện trong văn viết trang trọng để nhấn mạnh giả định về quá khứ. Đừng chọn 'Should' hay 'Were' - hai từ này dùng để đảo ngữ cho loại 1 và loại 2, chỉ có 'Had' mới dùng để đảo ngữ cho loại 3 vì mệnh đề gốc chia 'had known'." },
  { id: "c028", question: "_____ you see her, please give her this message. (formal)", options: ["If", "Should", "Were", "Had"], correctIndex: 1, explanation: "Đây là cách đảo ngữ trang trọng của câu điều kiện loại 1: 'Should you see her' = 'If you should see her' (nếu lỡ như/nếu tình cờ bạn gặp cô ấy). 'Should' trong cấu trúc này mang nghĩa 'lỡ như', nhấn mạnh khả năng không chắc chắn nhưng vẫn ở tương lai. Không chọn 'Had' hay 'Were' vì đó là đảo ngữ dành riêng cho loại 3 và loại 2, không phù hợp với ngữ cảnh dặn dò mang tính tương lai như câu này." },
  { id: "c029", question: "If I had studied medicine, I _____ a doctor now. (mixed)", options: ["am", "was", "would be", "would have been"], correctIndex: 2, explanation: "Đây là câu điều kiện hỗn hợp (mixed conditional): điều kiện ở quá khứ (If + had studied - quá khứ hoàn thành) nhưng kết quả lại ảnh hưởng đến hiện tại, nên mệnh đề chính chia 'would + V nguyên thể' chứ không phải 'would have + V3'. Từ 'now' ở cuối câu là dấu hiệu quan trọng cho thấy kết quả đang nói về hiện tại. Nếu không có 'now', câu sẽ là loại 3 thuần túy và đáp án đúng phải là 'would have been' - đây chính là điểm khác biệt cần ghi nhớ." },
  { id: "c030", question: "She _____ feel better now if she had rested yesterday.", options: ["will", "would", "could", "should"], correctIndex: 1, explanation: "Câu điều kiện hỗn hợp: điều kiện ở quá khứ (had rested yesterday) dẫn đến một kết quả ở hiện tại (feel better now), nên công thức là 'would + V nguyên thể' chứ không phải 'would have + V3'. Từ 'now' xác nhận kết quả đang xảy ra ở hiện tại, trong khi 'yesterday' xác nhận điều kiện thuộc về quá khứ - đặc trưng của câu hỗn hợp. Đừng chọn 'will' vì mệnh đề 'if' đã chia quá khứ hoàn thành, không thể đi cùng 'will'." },
  { id: "c031", question: "I wish I _____ to the concert last night.", options: ["go", "went", "had gone", "would go"], correctIndex: 2, explanation: "'Wish' + quá khứ hoàn thành (had gone) dùng để hối tiếc về một việc đã không làm trong quá khứ, cấu trúc này song song với câu điều kiện loại 3. Cụm 'last night' xác nhận đây là một sự việc đã qua nên không thể dùng 'went' (chỉ dùng cho ước muốn ở hiện tại). Ghi nhớ: wish + quá khứ đơn = ước hiện tại, wish + quá khứ hoàn thành = tiếc nuối quá khứ, đây là điểm phân biệt quan trọng." },
  { id: "c032", question: "If only it _____ raining! (Current wish for change)", options: ["stops", "stopped", "would stop", "had stopped"], correctIndex: 2, explanation: "'If only' + would + V dùng khi mong muốn một tình huống hiện tại thay đổi, thường diễn tả sự khó chịu hoặc mất kiên nhẫn với điều đang xảy ra. Gợi ý 'Current wish for change' trong câu cho biết đây là mong muốn về hiện tại, không phải quá khứ, nên không chọn 'had stopped'. 'Stopped' cũng sai vì 'if only' + quá khứ đơn chỉ dùng để ước về một trạng thái tĩnh (ví dụ ước mình giàu có), khác với mong muốn một hành động thay đổi như mưa ngừng rơi." },
  { id: "c033", question: "It's time we _____ home.", options: ["go", "went", "will go", "have gone"], correctIndex: 1, explanation: "Cấu trúc 'It's time + S + quá khứ đơn' (dùng hình thức giả định, không phải chia thì thật) diễn tả điều lẽ ra nên xảy ra ngay bây giờ nhưng chưa xảy ra. Câu này ngụ ý: đã đến lúc phải về nhà rồi (nhưng vẫn chưa về). Đừng chọn 'will go' - dù câu nói về tương lai gần, cấu trúc 'it's time' luôn dùng dạng quá khứ đơn đặc biệt này, không dùng 'will'." },
  { id: "c034", question: "I'd rather she _____ tell anyone about this.", options: ["doesn't", "didn't", "won't", "wouldn't"], correctIndex: 1, explanation: "Cấu trúc 'I'd rather + chủ ngữ khác + quá khứ đơn' dùng khi muốn người khác làm (hoặc không làm) điều gì ở hiện tại/tương lai, đây là hình thức giả định tương tự tinh thần câu điều kiện loại 2. Người nói muốn cô ấy không kể cho ai nên dùng 'didn't tell'. 'Doesn't' là hiện tại đơn thông thường, không đúng công thức - khi có chủ ngữ thứ hai sau 'I'd rather', động từ luôn phải lùi về quá khứ đơn dù ý nghĩa vẫn là hiện tại/tương lai." },
  { id: "c035", question: "_____ he to apply, he would be accepted.", options: ["If", "Were", "Should", "Had"], correctIndex: 1, explanation: "Đây là đảo ngữ trang trọng của câu điều kiện loại 2 với cấu trúc 'were to': 'Were he to apply' = 'If he were to apply' (nếu như anh ấy nộp đơn). Cấu trúc 'if...were to' thường dùng để nói về một khả năng giả định, ít chắc chắn xảy ra. Không chọn 'Had' - đó là đảo ngữ của loại 3 (had + V3), trong khi câu này không có 'have' ở vế kết quả nên phải là loại 2." },
  { id: "c036", question: "Suppose you _____ the job — what would you do?", options: ["get", "got", "will get", "would get"], correctIndex: 1, explanation: "'Suppose' (hoặc 'Supposing') + quá khứ đơn mang nghĩa tương đương 'if' trong câu điều kiện loại 2, dùng để đưa ra một tình huống giả định. Vế sau 'what would you do' xác nhận đây là loại 2 nên mệnh đề với 'suppose' cũng phải chia quá khứ đơn 'got'. Đừng chọn 'will get' - từ khi 'suppose' đóng vai trò như 'if', nó tuân theo đúng quy tắc thì của câu điều kiện tương ứng, ở đây là quá khứ đơn chứ không phải 'will'." },
  { id: "c037", question: "As long as you _____ the rules, you can stay.", options: ["follow", "followed", "will follow", "would follow"], correctIndex: 0, explanation: "'As long as' mang nghĩa 'miễn là, với điều kiện là', hoạt động giống hệt 'if' trong câu điều kiện loại 1: as long as + hiện tại đơn, + can/will + V. Việc tuân thủ quy định là điều hoàn toàn có thể thực hiện được nên chia hiện tại đơn 'follow'. Tránh chọn 'will follow' - giống mọi mệnh đề điều kiện loại 1 khác, phần sau 'as long as' không bao giờ dùng 'will'." },
  { id: "c038", question: "You won't improve _____ you practice every day.", options: ["if", "unless", "although", "despite"], correctIndex: 1, explanation: "'Unless' nghĩa là 'nếu... không', nên câu này thực chất là: 'You won't improve if you don't practice every day' - bạn sẽ không tiến bộ nếu không luyện tập mỗi ngày. Đây vẫn là cấu trúc câu điều kiện loại 1 với 'unless + hiện tại đơn'. 'If' bị loại vì nếu dùng 'if' thì câu sẽ mang nghĩa ngược lại (không luyện tập thì sẽ không tiến bộ - vô lý), còn 'although/despite' không diễn tả điều kiện mà diễn tả sự tương phản." },
  { id: "c039", question: "If the road _____ not icy, the accident wouldn't have happened.", options: ["were", "was", "had been", "is"], correctIndex: 2, explanation: "Câu điều kiện loại 3: mệnh đề kết quả 'wouldn't have happened' (would not have + V3) đòi hỏi mệnh đề 'if' phải chia quá khứ hoàn thành, tức là 'had been'. Câu nói về một sự việc đã xảy ra trong quá khứ - con đường đã bị đóng băng và tai nạn đã xảy ra - nên không thể dùng 'were/was' (quá khứ đơn, thuộc loại 2). Nhớ quy tắc vàng: 'would have' ở vế kết quả luôn đi cùng 'had + V3' ở vế điều kiện." },
  { id: "c040", question: "Provided _____ you work hard, you'll get the promotion.", options: ["if", "that", "which", "whether"], correctIndex: 1, explanation: "'Provided that' (hoặc 'providing that') là một cụm mang nghĩa 'nếu, miễn là', được dùng thay cho 'if' trong văn phong trang trọng hơn, và vẫn theo công thức câu điều kiện loại 1: provided that + hiện tại đơn, + will + V. Ở đây cần điền 'that' để hoàn chỉnh cụm từ 'provided that'. 'If' bị loại vì 'provided' đã tự mang nghĩa điều kiện, không cần thêm 'if' phía sau, chỉ cần 'that' để nối mệnh đề." },
  { id: "c041", question: "If I _____ the answer, I'd tell you immediately. (But I don't know)", options: ["know", "knew", "had known", "would know"], correctIndex: 1, explanation: "Gợi ý trong ngoặc '(But I don't know)' xác nhận đây là một giả định trái với thực tế ở hiện tại - câu điều kiện loại 2: If + quá khứ đơn, + would + V. Vì thực tế người nói không biết câu trả lời, mệnh đề 'if' phải chia 'knew'. Đừng chọn 'know' (hiện tại đơn) - đó là công thức loại 1 dùng cho khả năng có thật, không phù hợp khi câu đã khẳng định rõ điều đó không đúng ở hiện tại." },
  { id: "c042", question: "She _____ go home early if she finishes all her work.", options: ["can", "could", "might", "may"], correctIndex: 0, explanation: "Câu điều kiện loại 1: If + hiện tại đơn (finishes), + can/will + V. Việc hoàn thành công việc là điều hoàn toàn khả thi trong hiện tại/tương lai gần nên đây là loại 1, và 'can' phù hợp nhất để diễn tả sự cho phép (được về sớm nếu xong việc). Các từ 'could/might/may' vẫn có thể chấp nhận về ngữ pháp nhưng mang sắc thái không chắc chắn hơn 'can', trong khi ngữ cảnh câu này thể hiện một điều kiện rõ ràng, dứt khoát." },
  { id: "c043", question: "Even if she _____ the chance, she wouldn't do it.", options: ["has", "had", "would have", "will have"], correctIndex: 1, explanation: "'Even if' + quá khứ đơn là câu điều kiện loại 2, dùng để nhấn mạnh rằng dù điều kiện đó có xảy ra (dù là giả định) thì kết quả vẫn không thay đổi. Vế chính 'wouldn't do it' xác nhận đây là loại 2 nên mệnh đề với 'even if' phải chia 'had'. Đừng nhầm 'even if' với 'if' đơn thuần rồi chọn 'has' - vì vế sau đã dùng 'would', bắt buộc vế 'even if' phải đồng bộ ở quá khứ đơn." },
  { id: "c044", question: "If he _____ more careful, he wouldn't have had the accident.", options: ["is", "was", "were", "had been"], correctIndex: 3, explanation: "Câu điều kiện loại 3: vế kết quả 'wouldn't have had' (would not have + V3) cho biết đây là một việc đã xảy ra trong quá khứ, nên mệnh đề 'if' phải chia quá khứ hoàn thành 'had been'. Câu nói về một tai nạn đã xảy ra vì anh ấy đã không cẩn thận. 'Were' rất dễ bị chọn nhầm vì nó đúng ngữ pháp cho loại 2, nhưng ở đây thì của vế chính là 'have had' (loại 3) nên bắt buộc phải dùng 'had been'." },
  { id: "c045", question: "She wouldn't have missed the bus _____ she woken up earlier.", options: ["if", "had", "should", "were"], correctIndex: 1, explanation: "Đây là câu điều kiện loại 3 ở dạng đảo ngữ, bỏ từ 'if' và đảo 'had' lên trước chủ ngữ: 'had she woken up' = 'if she had woken up'. Vế chính 'wouldn't have missed' xác nhận công thức loại 3 nên cần 'had' để tạo cụm 'had she woken up' đúng cấu trúc đảo ngữ. Không chọn 'if' vì nếu dùng 'if' thì câu thiếu động từ 'had' đứng trước chủ ngữ (if she had woken up mới đủ, nhưng ở đây chỗ trống chỉ có một từ)." },
  { id: "c046", question: "What would happen if everyone _____ to recycle?", options: ["refuse", "refuses", "refused", "will refuse"], correctIndex: 2, explanation: "Câu điều kiện loại 2: vế chính 'What would happen' cho thấy đây là một giả định mang tính khái quát, không nói về một tình huống thực tế cụ thể, nên mệnh đề 'if' phải chia quá khứ đơn 'refused'. Đây là kiểu câu thường dùng để bàn luận giả thuyết ('what if' scenarios). 'Refuses' (hiện tại đơn) sai vì không khớp với 'would' đã cho ở vế chính - would luôn đi cùng if + quá khứ đơn." },
  { id: "c047", question: "If only I _____ studied harder when I was young!", options: ["study", "studied", "had studied", "have studied"], correctIndex: 2, explanation: "'If only' + quá khứ hoàn thành (had studied) dùng để bày tỏ sự hối tiếc sâu sắc về một việc đã không làm trong quá khứ, mạnh hơn cách nói thông thường bằng 'wish'. Cụm 'when I was young' xác nhận đây là chuyện đã qua từ lâu nên cần quá khứ hoàn thành. 'Studied' (quá khứ đơn) sai vì 'if only' + quá khứ đơn chỉ dùng cho ước muốn về hiện tại, không phù hợp với bối cảnh quá khứ rõ ràng ở đây." },
  { id: "c048", question: "I'll lend you the book _____ you return it by Friday.", options: ["if", "unless", "provided that", "as long as"], correctIndex: 2, explanation: "'Provided that' nghĩa là 'với điều kiện là', phù hợp nhất trong ngữ cảnh đưa ra một điều kiện ràng buộc rõ ràng để cho mượn sách - đây là câu điều kiện loại 1 ở dạng trang trọng. Cả 4 lựa chọn đều có thể mang nghĩa điều kiện, nhưng 'provided that' nhấn mạnh tính ràng buộc như một thỏa thuận, khớp với ngữ cảnh 'phải trả sách trước thứ Sáu' hơn 'if' chung chung. 'Unless' bị loại vì nó mang nghĩa phủ định, sẽ đổi hẳn ý nghĩa câu." },
  { id: "c049", question: "She might pass the test _____ she studies tonight.", options: ["unless", "if", "although", "despite"], correctIndex: 1, explanation: "Câu điều kiện loại 1: if + hiện tại đơn (studies), + might/may/will + V. Việc học tối nay là điều hoàn toàn có thể xảy ra nên đây là điều kiện thực tế, dùng 'if' để nối hai mệnh đề. 'Unless' sẽ làm sai nghĩa câu (biến thành 'trừ khi cô ấy học thì sẽ đỗ' - ngược nghĩa mong muốn); còn 'although/despite' chỉ dùng để diễn tả sự tương phản, không phải điều kiện." },
  { id: "c050", question: "If the alarm _____ gone off, I would have overslept.", options: ["didn't", "hadn't", "wouldn't have", "hasn't"], correctIndex: 1, explanation: "Câu điều kiện loại 3 ở thể phủ định: If + hadn't + V3 (hadn't gone off), + would have + V3. Vế chính 'would have overslept' xác nhận công thức loại 3, nên mệnh đề 'if' cần 'hadn't' để tạo thành 'hadn't gone off' (quá khứ hoàn thành phủ định). 'Didn't' sai vì đó là dạng phủ định của quá khứ đơn, không tạo được cụm quá khứ hoàn thành cần thiết ở đây." },
  { id: "c051", question: "If water reaches 0°C, it _____ into ice.", options: ["freezes", "froze", "will freeze", "would freeze"], correctIndex: 0, explanation: "Câu điều kiện loại 0 nói về một sự thật khoa học luôn đúng: If + hiện tại đơn, + hiện tại đơn. Nước đóng băng ở 0°C là một quy luật vật lý không đổi, không phụ thuộc vào thời gian hay hoàn cảnh cụ thể, nên cả hai mệnh đề đều chia hiện tại đơn, 'freezes' hợp với chủ ngữ số ít 'it'. 'Will freeze' là lựa chọn gây nhầm lẫn phổ biến vì nghe có vẻ đúng ngữ pháp, nhưng loại 0 không bao giờ dùng 'will' vì đây không phải một dự đoán mà là một quy luật chắc chắn." },
  { id: "c052", question: "If you _____ a coin, it lands on heads or tails.", options: ["flip", "flipped", "will flip", "would flip"], correctIndex: 0, explanation: "Câu điều kiện loại 0: If + hiện tại đơn, + hiện tại đơn, dùng để nói về một điều luôn đúng bất kể ai thực hiện hay khi nào. Tung một đồng xu thì luôn rơi vào mặt sấp hoặc ngửa - đây là quy luật hiển nhiên nên chia 'flip' ở hiện tại đơn. Tránh chọn 'will flip' - dấu hiệu nhận biết loại 0 là cả hai mệnh đề đều ở hiện tại đơn, không mệnh đề nào chứa 'will'." },
  { id: "c053", question: "If she calls, _____ her to wait.", options: ["tell", "telling", "told", "tells"], correctIndex: 0, explanation: "Câu điều kiện loại 1 nhưng mệnh đề kết quả ở dạng mệnh lệnh (imperative) thay vì 'will + V', dùng để đưa ra chỉ dẫn hoặc yêu cầu: If + hiện tại đơn, + động từ nguyên thể. Vì đây là một câu dặn dò/ra lệnh nên dùng 'tell' (nguyên mẫu, không chia theo ngôi). Đừng chọn 'tells' - động từ trong câu mệnh lệnh không bao giờ thêm 's' hay chia theo chủ ngữ." },
  { id: "c054", question: "He'll get the job _____ he impresses at the interview.", options: ["unless", "if", "although", "in case"], correctIndex: 1, explanation: "Câu điều kiện loại 1: if + hiện tại đơn (impresses), + will + V (he'll get). Việc gây ấn tượng tốt trong buổi phỏng vấn là điều kiện thực tế dẫn đến kết quả có việc làm, nên dùng 'if' để nối hai vế theo quan hệ nhân quả thuận. 'Unless' sẽ đảo ngược nghĩa câu (trừ khi anh ấy gây ấn tượng thì mới không được nhận - vô lý về ngữ nghĩa mong muốn ở đây)." },
  { id: "c055", question: "If you _____ more vegetables, you'll be healthier.", options: ["eat", "will eat", "ate", "had eaten"], correctIndex: 0, explanation: "Câu điều kiện loại 1: If + hiện tại đơn (eat), + will + V (you'll be). Ăn nhiều rau củ hơn là một hành động hoàn toàn có thể thực hiện được, dẫn đến kết quả có khả năng xảy ra trong tương lai, nên mệnh đề 'if' chia hiện tại đơn. 'Ate' và 'had eaten' đều sai vì đó là công thức của loại 2 và loại 3, chỉ dùng cho giả định hoặc chuyện đã qua, không phù hợp với lời khuyên mang tính thực tế như câu này." },
  { id: "c056", question: "Take an umbrella in case it _____.", options: ["rains", "will rain", "rained", "would rain"], correctIndex: 0, explanation: "'In case' + hiện tại đơn dùng để nói về một biện pháp phòng ngừa cho một khả năng có thể xảy ra trong tương lai, mang tinh thần gần giống câu điều kiện loại 1. Mang ô phòng khi trời có thể mưa là một hành động đề phòng hợp lý ở hiện tại/tương lai gần, nên chia 'rains'. Khác với 'if', sau 'in case' không bao giờ dùng 'will', dù đang nói về một sự việc trong tương lai." },
  { id: "c057", question: "If I _____ you, I'd see a doctor about that cough.", options: ["am", "was", "were", "be"], correctIndex: 2, explanation: "Cấu trúc lời khuyên quen thuộc 'If I were you, I'd...' luôn dùng 'were' bất kể chủ ngữ là gì - đây là hình thức giả định đặc biệt của to be trong câu điều kiện loại 2. Đây là một giả định phi thực tế vì người nói không thể là người nghe, nên không dùng 'am' hay 'was'. Hãy học thuộc cả cụm 'If I were you' như một công thức cố định khi đưa ra lời khuyên." },
  { id: "c058", question: "She could learn faster if she _____ more time studying.", options: ["spend", "spends", "spent", "had spent"], correctIndex: 2, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (spent), + could + V (could learn). Đây là một giả định về hiện tại - thực tế cô ấy chưa dành đủ thời gian học - nên mệnh đề 'if' chia quá khứ đơn. 'Had spent' dễ gây nhầm vì nghe giống nói về quá khứ, nhưng vế chính dùng 'could learn' (không có 'have'), nên phải khớp với công thức loại 2 là 'spent', không phải quá khứ hoàn thành của loại 3." },
  { id: "c059", question: "If I _____ a bird, I'd fly around the world.", options: ["am", "was", "were", "be"], correctIndex: 2, explanation: "Câu điều kiện loại 2 diễn tả một giả định hoàn toàn phi thực tế: If + were, + would + V. Con người không thể là chim nên đây là ví dụ điển hình của giả định trái thực tế tuyệt đối, và theo quy tắc chia to be ở loại 2, luôn dùng 'were' cho mọi chủ ngữ kể cả 'I'. Đừng chọn 'was' - dù đúng ngữ pháp thông thường, trong câu điều kiện loại 2 chuẩn mực 'were' mới là hình thức được ưu tiên." },
  { id: "c060", question: "Would you mind if I _____ the window?", options: ["open", "opens", "opened", "will open"], correctIndex: 2, explanation: "'Would you mind if I + quá khứ đơn' là cách xin phép lịch sự, mang cấu trúc nhẹ nhàng của câu điều kiện loại 2 dù không thực sự nói về điều giả định xa vời. Đây là một quy tắc lịch sự cố định trong tiếng Anh giao tiếp: hỏi xin phép bằng 'Would you mind if I + quá khứ đơn' nghe lịch sự và trang trọng hơn 'Do you mind if I + hiện tại đơn'. 'Will open' sai vì mệnh đề 'if' sau 'would you mind' không bao giờ dùng 'will'." },
  { id: "c061", question: "If only she _____ more patient with him!", options: ["is", "was", "were", "has been"], correctIndex: 2, explanation: "'If only' + were (hình thức giả định của to be) dùng để ước ao một điều trái với thực tế ở hiện tại - ở đây là mong cô ấy kiên nhẫn hơn (nhưng thực tế cô ấy không kiên nhẫn). Giống câu điều kiện loại 2, 'to be' sau 'if only' luôn chia 'were' bất kể chủ ngữ số ít hay số nhiều. 'Was' tuy phổ biến trong văn nói nhưng 'were' mới là lựa chọn chuẩn mực được ưu tiên trong các bài tập ngữ pháp." },
  { id: "c062", question: "He _____ have become a great athlete if he'd trained harder.", options: ["could", "will", "would", "should"], correctIndex: 0, explanation: "Câu điều kiện loại 3: mệnh đề 'if' đã ở dạng viết tắt 'he'd trained' = 'he had trained' (quá khứ hoàn thành), nên vế chính phải dùng 'could have + V3' để diễn tả khả năng đã có thể xảy ra nhưng đã không xảy ra. 'Could have' nhấn mạnh tiềm năng bị bỏ lỡ, khác sắc thái nhẹ so với 'would have'. 'Will' hoàn toàn sai vì không bao giờ xuất hiện trong câu điều kiện loại 3." },
  { id: "c063", question: "If they had left earlier, they _____ caught the train.", options: ["will have", "would have", "could", "had"], correctIndex: 1, explanation: "Câu điều kiện loại 3: If + had left (quá khứ hoàn thành), + would have + V3 (caught). Việc rời đi sớm hơn đã không xảy ra trong thực tế nên họ đã lỡ chuyến tàu, đây là giả định thuần túy về quá khứ. 'Will have' sai hoàn toàn vì 'will' không tồn tại trong công thức loại 3; 'could' thiếu 'have' nên không tạo được cụm quá khứ hoàn thành cần thiết." },
  { id: "c064", question: "She wouldn't have been so stressed _____ she'd asked for help.", options: ["if", "unless", "provided that", "although"], correctIndex: 0, explanation: "Câu điều kiện loại 3: if + had asked (quá khứ hoàn thành, viết tắt là 'she'd asked'), + wouldn't have been (would not have + V3). Đây là quan hệ nhân quả thuận trong quá khứ (nếu cô ấy đã nhờ giúp đỡ thì đã không căng thẳng), nên dùng 'if' để nối hai mệnh đề. 'Unless' sẽ đảo ngược nghĩa câu, còn 'provided that/although' không diễn tả đúng mối quan hệ điều kiện - kết quả như 'if'." },
  { id: "c065", question: "_____ she been more careful, she wouldn't have made those mistakes.", options: ["If", "Had", "Should", "Were"], correctIndex: 1, explanation: "Đảo ngữ câu điều kiện loại 3: 'Had she been more careful' = 'If she had been more careful', đảo trợ động từ 'had' lên trước chủ ngữ và bỏ 'if'. Vế chính 'wouldn't have made' (would not have + V3) xác nhận đây là loại 3 nên cần 'Had' để mở đầu câu đảo ngữ. 'Were' chỉ dùng để đảo ngữ cho loại 2 (Were she...), không phù hợp khi vế chính đã có 'have made'." },
  { id: "c066", question: "If it hadn't been for your support, I _____ given up.", options: ["would have", "will have", "had", "have"], correctIndex: 0, explanation: "Cấu trúc cố định 'If it hadn't been for + N' (nếu không nhờ có...) là một dạng đặc biệt của câu điều kiện loại 3, và mệnh đề kết quả luôn theo công thức 'would have + V3'. Câu ngụ ý: nhờ có sự ủng hộ của bạn nên tôi đã không từ bỏ. 'Will have' sai vì đây là chuyện đã xảy ra trong quá khứ, không phải một khả năng tương lai để dùng 'will'." },
  { id: "c067", question: "If I _____ born in a different country, my life would be very different now.", options: ["were", "was", "had been", "am"], correctIndex: 2, explanation: "Đây là câu điều kiện hỗn hợp: điều kiện thuộc về quá khứ (sinh ra ở đâu là chuyện đã rồi, không thể thay đổi) nên mệnh đề 'if' chia quá khứ hoàn thành 'had been', nhưng kết quả lại ảnh hưởng đến hiện tại ('now'), nên vế chính dùng 'would be' (không có 'have'). Đây là điểm đặc trưng để nhận diện câu hỗn hợp: nhìn vào trạng từ chỉ thời gian ('now') ở vế kết quả. 'Were' sai vì bản chất việc 'được sinh ra' luôn là một sự kiện đã hoàn tất trong quá khứ, phải dùng thì hoàn thành chứ không phải quá khứ đơn." },
  { id: "c068", question: "She _____ a professor now if she hadn't dropped out of university.", options: ["will be", "would be", "would have been", "is"], correctIndex: 1, explanation: "Câu điều kiện hỗn hợp: điều kiện ở quá khứ (hadn't dropped out - quá khứ hoàn thành) nhưng ảnh hưởng đến hiện tại, thể hiện qua từ 'now', nên mệnh đề kết quả dùng 'would be' (không thêm 'have'). Nếu không có 'now', câu sẽ trở thành loại 3 thuần túy và đáp án đúng phải là 'would have been'. Đây là lỗi rất dễ mắc: thấy 'hadn't' ở vế 'if' liền chọn ngay 'would have been' mà quên kiểm tra dấu hiệu thời gian ở vế chính." },
  { id: "c069", question: "If he _____ the lottery last year, he would be rich now.", options: ["wins", "won", "had won", "would win"], correctIndex: 2, explanation: "Câu điều kiện hỗn hợp: 'last year' cho biết điều kiện thuộc về quá khứ nên mệnh đề 'if' chia quá khứ hoàn thành 'had won', còn 'now' ở vế kết quả cho biết ảnh hưởng đang diễn ra ở hiện tại nên chỉ cần 'would be' chứ không phải 'would have been'. Đây là dạng hỗn hợp phổ biến: nguyên nhân quá khứ - kết quả hiện tại. 'Won' (quá khứ đơn) sai vì không đủ mạnh để diễn tả một sự kiện đã hoàn toàn kết thúc và có ảnh hưởng kéo dài đến hiện tại như 'had won'." },
  { id: "c070", question: "I wish I _____ harder at school.", options: ["work", "worked", "had worked", "would work"], correctIndex: 2, explanation: "'Wish' + quá khứ hoàn thành (had worked) dùng để hối tiếc về một việc đã không làm trong quá khứ - ở đây là đã không chăm chỉ học khi còn đi học. Ngữ cảnh 'at school' ngụ ý đây là chuyện đã qua từ lâu, không phải hiện tại, nên cần quá khứ hoàn thành. 'Worked' (quá khứ đơn) chỉ đúng khi ước về một trạng thái ở hiện tại, không phù hợp khi rõ ràng đang nói về một giai đoạn đã kết thúc." },
  { id: "c071", question: "I wish he _____ stop interrupting me!", options: ["will", "would", "could", "should"], correctIndex: 1, explanation: "'Wish' + would + V dùng để bày tỏ mong muốn ai đó (không phải bản thân người nói) thay đổi một hành vi gây khó chịu ở hiện tại, thường mang hàm ý phàn nàn. Câu này thể hiện sự bực bội vì bị ngắt lời liên tục. Không dùng 'will' - sau 'wish' không bao giờ chia 'will', chỉ có 'would' (dạng quá khứ của will) mới đúng ngữ pháp trong cấu trúc này." },
  { id: "c072", question: "She wishes she _____ more money right now.", options: ["has", "had", "would have", "will have"], correctIndex: 1, explanation: "'Wish' + quá khứ đơn (had) dùng để ước về một điều không có thật ở hiện tại, cấu trúc song song với câu điều kiện loại 2. Cụm 'right now' xác nhận đây là ước muốn về hiện tại nên chỉ cần quá khứ đơn 'had', không cần quá khứ hoàn thành. 'Has' (hiện tại đơn) sai vì động từ sau 'wish' luôn phải lùi một thì so với hiện tại thực, đó là quy tắc bắt buộc của cấu trúc này." },
  { id: "c073", question: "I wish it _____ so cold — I hate winter!", options: ["isn't", "wasn't", "weren't", "hadn't been"], correctIndex: 2, explanation: "'Wish' + weren't (hình thức giả định của to be, dùng cho mọi chủ ngữ) để ước về một trạng thái hiện tại không như mong muốn - ở đây là ước trời bớt lạnh. Vế sau 'I hate winter' xác nhận đây là cảm nhận về hiện tại nên không dùng 'hadn't been' (dành cho quá khứ). Với động từ to be sau 'wish', 'weren't' được ưu tiên hơn 'wasn't' trong văn phong chuẩn mực, giống quy tắc của câu điều kiện loại 2." },
  { id: "c074", question: "If only we _____ booked the hotel earlier!", options: ["book", "booked", "had booked", "would book"], correctIndex: 2, explanation: "'If only' + quá khứ hoàn thành (had booked) dùng để hối tiếc mạnh mẽ về một việc đã không làm trong quá khứ - ở đây là đã không đặt phòng khách sạn sớm hơn. Từ 'earlier' xác nhận đây là hành động đáng lẽ nên xảy ra trước đó nhưng đã không xảy ra. 'Booked' (quá khứ đơn) sai vì chỉ phù hợp khi ước về hiện tại, trong khi ngữ cảnh này rõ ràng đang tiếc nuối về một cơ hội đã qua." },
  { id: "c075", question: "I'd rather you _____ here tomorrow, not today.", options: ["come", "came", "will come", "would come"], correctIndex: 1, explanation: "Cấu trúc 'I'd rather + chủ ngữ khác + quá khứ đơn' dùng để bày tỏ mong muốn về hành động của người khác trong hiện tại hoặc tương lai, dù chia ở dạng quá khứ. Người nói muốn người nghe đến vào ngày mai chứ không phải hôm nay, nên dùng 'came'. 'Will come' sai vì khi có chủ ngữ thứ hai theo sau 'I'd rather', động từ luôn phải ở dạng quá khứ đơn giả định, không dùng 'will' dù đang nói về tương lai." },
  { id: "c076", question: "It's high time she _____ a decision.", options: ["make", "makes", "made", "has made"], correctIndex: 2, explanation: "'It's high time' + quá khứ đơn (made) là biến thể nhấn mạnh hơn của 'it's time', diễn tả một việc đáng lẽ phải làm từ trước nhưng đến giờ vẫn chưa làm. Câu ngụ ý cô ấy lẽ ra phải quyết định từ lâu rồi. Dù nói về hiện tại/tương lai gần, cấu trúc 'it's (high) time' luôn đòi hỏi động từ chia ở quá khứ đơn giả định, không dùng hiện tại đơn 'makes' hay hiện tại hoàn thành 'has made'." },
  { id: "c077", question: "I'd rather _____ than take the bus.", options: ["walk", "walked", "to walk", "walking"], correctIndex: 0, explanation: "Khi 'I'd rather' không có chủ ngữ thứ hai theo sau (chỉ nói về hành động của chính người nói), động từ theo sau phải là nguyên thể không 'to' (bare infinitive) - ở đây là 'walk'. Đây là điểm khác biệt quan trọng: có chủ ngữ khác thì dùng quá khứ đơn (như c075), còn cùng chủ ngữ thì dùng nguyên mẫu không 'to'. 'To walk' và 'walking' đều sai vì cấu trúc 'would rather' không đi với to-infinitive hay V-ing." },
  { id: "c078", question: "Imagine you _____ to live on a deserted island for a year.", options: ["have", "had", "were", "will have"], correctIndex: 2, explanation: "'Imagine' + were (hoặc quá khứ đơn) dùng để đưa ra một tình huống giả định hoàn toàn phi thực tế, mang tinh thần giống câu điều kiện loại 2. Sống trên hoang đảo một năm là một kịch bản tưởng tượng, không phải thực tế đang xảy ra, nên chia 'were' (to be trong câu giả định luôn dùng 'were'). 'Have' sai vì đây không phải chuyện đang thực sự xảy ra ở hiện tại mà chỉ là một bài tập tưởng tượng." },
  { id: "c079", question: "Suppose she _____ right — what would we do?", options: ["is", "was", "were", "had been"], correctIndex: 2, explanation: "'Suppose' + were dùng để đưa ra một giả định phi thực tế, tương đương 'if' trong câu điều kiện loại 2. Vế sau 'what would we do' xác nhận đây là giả định nên 'suppose' cũng phải chia theo quy tắc của loại 2. Với động từ to be, 'were' phổ biến hơn 'was' trong văn viết trang trọng và các cấu trúc giả định như 'suppose', dù 'was' vẫn được chấp nhận trong văn nói." },
  { id: "c080", question: "On condition that you _____ our terms, we'll sign the contract.", options: ["accept", "accepted", "will accept", "would accept"], correctIndex: 0, explanation: "'On condition that' nghĩa là 'với điều kiện là', một cách diễn đạt trang trọng thay cho 'if', vẫn theo đúng công thức câu điều kiện loại 1: on condition that + hiện tại đơn, + will + V. Việc chấp nhận điều khoản là một điều kiện thực tế để ký hợp đồng, nên chia hiện tại đơn 'accept'. 'Will accept' sai vì giống mọi mệnh đề điều kiện khác, phần sau 'on condition that' không bao giờ dùng 'will'." },
  { id: "c081", question: "You can borrow my car _____ you drive carefully.", options: ["unless", "as long as", "although", "in case"], correctIndex: 1, explanation: "'As long as' nghĩa là 'miễn là, với điều kiện là', diễn tả điều kiện cần thiết để một việc được phép xảy ra - ở đây là được mượn xe với điều kiện lái xe cẩn thận. Đây là cách dùng phổ biến của 'as long as' tương đương với 'if' trong câu điều kiện loại 1. 'Unless' sẽ đổi nghĩa thành 'trừ khi bạn lái cẩn thận thì mới không được mượn' - vô lý so với ý muốn khuyến khích lái xe an toàn." },
  { id: "c082", question: "_____ to be late, please let me know in advance.", options: ["If you are", "Should you be", "Were you", "Had you been"], correctIndex: 1, explanation: "Đảo ngữ trang trọng của câu điều kiện loại 1: 'Should you be late' = 'If you should be late' (nếu lỡ như/nếu chẳng may bạn đến muộn). Cấu trúc này thường dùng trong văn phong lịch sự, trang trọng như email công việc. 'Were you' và 'Had you been' là đảo ngữ của loại 2 và loại 3, không phù hợp khi nói về một khả năng thực tế trong tương lai như câu này." },
  { id: "c083", question: "_____ I been informed earlier, I could have helped.", options: ["If", "Had", "Should", "Were"], correctIndex: 1, explanation: "Đảo ngữ câu điều kiện loại 3: 'Had I been informed' = 'If I had been informed', đảo 'had' lên trước chủ ngữ. Vế chính 'could have helped' (could have + V3) xác nhận đây là loại 3, nói về một cơ hội đã bị bỏ lỡ trong quá khứ. 'Should' và 'Were' dùng để đảo ngữ cho loại 1 và loại 2, không khớp với 'could have' ở vế kết quả." },
  { id: "c084", question: "_____ he to change his mind, the deal would fall through.", options: ["If", "Had", "Should", "Were"], correctIndex: 3, explanation: "Đảo ngữ câu điều kiện loại 2 với cấu trúc 'were to': 'Were he to change his mind' = 'If he were to change his mind' - một giả định về khả năng đổi ý trong tương lai. Vế chính 'would fall through' (would + V, không có 'have') xác nhận đây là loại 2 chứ không phải loại 3. 'Had' sẽ tạo thành đảo ngữ loại 3, không khớp vì vế kết quả thiếu 'have'." },
  { id: "c085", question: "She'll succeed _____ she keeps trying.", options: ["unless", "if", "although", "because"], correctIndex: 1, explanation: "Câu điều kiện loại 1 đơn giản: if + hiện tại đơn (keeps trying), + will + V (she'll succeed). Việc tiếp tục cố gắng là điều kiện thực tế dẫn đến thành công, thể hiện quan hệ nhân quả thuận nên dùng 'if'. 'Unless' sẽ đảo ngược nghĩa (trừ khi cô ấy tiếp tục cố gắng - ngược với ý khuyến khích); 'because/although' không diễn tả điều kiện mà diễn tả nguyên nhân hoặc sự tương phản." },
  { id: "c086", question: "If you _____ your homework, you can watch TV.", options: ["finish", "finished", "will finish", "had finished"], correctIndex: 0, explanation: "Câu điều kiện loại 1: If + hiện tại đơn (finish), + can/may + V để diễn tả sự cho phép có điều kiện. Hoàn thành bài tập là một việc hoàn toàn khả thi trong hiện tại nên mệnh đề 'if' chia hiện tại đơn. 'Will finish' sai vì mệnh đề 'if' không bao giờ dùng 'will', dù cả câu đang nói về một việc sắp xảy ra." },
  { id: "c087", question: "Unless she _____ her attitude, she'll lose her job.", options: ["change", "changes", "changed", "will change"], correctIndex: 1, explanation: "'Unless' + hiện tại đơn (câu điều kiện loại 1) tương đương 'if...not': câu này nghĩa là nếu cô ấy không thay đổi thái độ thì sẽ mất việc. Vì chủ ngữ 'she' là ngôi thứ ba số ít nên động từ phải thêm 's' thành 'changes', đây là lỗi chia động từ dễ mắc. 'Change' (không 's') sai về mặt hòa hợp chủ ngữ - động từ, dù đúng loại thì." },
  { id: "c088", question: "She _____ been more successful if she had chosen a different career.", options: ["could have", "will have", "would", "might"], correctIndex: 0, explanation: "Câu điều kiện loại 3: mệnh đề 'if' đã chia 'had chosen' (quá khứ hoàn thành) nên vế chính cần 'could have + V3' để diễn tả một khả năng đã có thể xảy ra nhưng thực tế đã không xảy ra (cô ấy đã không chọn nghề khác nên không thành công hơn). 'Will have' sai hoàn toàn vì 'will' không bao giờ xuất hiện ở loại 3; 'would' và 'might' thiếu 'have' nên không tạo được đúng cụm động từ hoàn thành cần thiết." },
  { id: "c089", question: "If only there _____ more hours in the day!", options: ["are", "were", "had been", "will be"], correctIndex: 1, explanation: "'If only' + were dùng để ước về một thực tế không thể thay đổi ở hiện tại - mong muốn có nhiều giờ hơn trong ngày (điều không thể). Với cấu trúc 'there is/are' ở dạng giả định, 'were' được dùng thay cho 'was' theo quy tắc chia to be trong câu điều kiện loại 2. 'Are' (hiện tại đơn) sai vì đây là một ước muốn phi thực tế, không phải phát biểu về thực tế hiện có." },
  { id: "c090", question: "I wish I _____ flying — I'd travel more.", options: ["like", "liked", "didn't mind", "don't mind"], correctIndex: 2, explanation: "'Wish' + quá khứ đơn (didn't mind) dùng để ước về một trạng thái cảm xúc hiện tại không như mong muốn - người nói hiện tại ngại/sợ bay nên ít đi du lịch. Vế sau 'I'd travel more' (would travel - kết quả giả định ở hiện tại) củng cố đây là ước muốn về hiện tại. 'Don't mind' (hiện tại đơn) sai vì động từ sau 'wish' luôn phải lùi một thì, không được giữ nguyên thì hiện tại." },
  { id: "c091", question: "If he _____ his glasses, he would be able to read this.", options: ["has", "had", "were having", "would have"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (had), + would + V (would be able to). Thực tế anh ấy không có kính bên mình nên đây là giả định trái thực tế ở hiện tại. 'Has' (hiện tại đơn) sai vì không khớp thì với 'would' ở vế chính - would luôn đòi hỏi if + quá khứ đơn, không phải hiện tại đơn." },
  { id: "c092", question: "She might have passed if she _____ the night before.", options: ["studies", "studied", "had studied", "was studying"], correctIndex: 2, explanation: "Câu điều kiện loại 3: If + had studied (quá khứ hoàn thành), + might have + V3 (might have passed). Cụm 'the night before' xác nhận đây là chuyện đã qua, một cơ hội học tập đã bị bỏ lỡ. 'Studied' (quá khứ đơn) sai vì vế chính đã dùng 'might have passed' (loại 3), đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành, không phải quá khứ đơn của loại 2." },
  { id: "c093", question: "What would you have said if she _____ the truth?", options: ["tells", "told", "has told", "had told"], correctIndex: 3, explanation: "Câu hỏi ở câu điều kiện loại 3: What would you have said if + had + V3? Vế chính 'would you have said' xác nhận công thức loại 3 nên mệnh đề 'if' phải chia quá khứ hoàn thành 'had told'. 'Told' (quá khứ đơn) là bẫy phổ biến vì nghe tự nhiên nhưng chỉ đúng ở loại 2, không tương thích với 'would have said' ở vế chính." },
  { id: "c094", question: "I'd better leave now _____ I miss the last bus.", options: ["if", "unless", "in case", "provided that"], correctIndex: 2, explanation: "'In case' dùng để nói về một hành động phòng ngừa cho một khả năng có thể xảy ra - ở đây là rời đi sớm để phòng lỡ chuyến xe buýt cuối. Khác với 'if' (chỉ hành động khi điều kiện xảy ra), 'in case' diễn tả việc chuẩn bị trước đề phòng. 'Unless' sai vì sẽ đổi nghĩa hoàn toàn (trừ khi tôi lỡ xe mới rời đi - vô lý), không phù hợp với ý phòng ngừa của câu." },
  { id: "c095", question: "She _____ have taken the job if the salary had been higher.", options: ["will", "would", "could", "should"], correctIndex: 1, explanation: "Câu điều kiện loại 3: If + had been (quá khứ hoàn thành), + would have + V3 (would have taken). Mức lương thực tế đã không cao hơn nên cô ấy đã không nhận công việc, đây là giả định thuần túy về quá khứ. 'Will' sai hoàn toàn vì không bao giờ xuất hiện trong công thức câu điều kiện loại 3, chỉ 'would have' mới đúng khi kết hợp với 'had been' ở mệnh đề 'if'." },
  { id: "c096", question: "If I hadn't been so nervous, I _____ better in the interview.", options: ["perform", "performed", "would perform", "would have performed"], correctIndex: 3, explanation: "Câu điều kiện loại 3: If + hadn't been (quá khứ hoàn thành phủ định), + would have + V3 (would have performed). Việc lo lắng quá mức đã ảnh hưởng đến buổi phỏng vấn đã qua, nên đây là giả định về một kết quả khác đã có thể xảy ra. 'Would perform' thiếu 'have' nên sai - đó là công thức của loại 2, không khớp với mệnh đề 'if' đã ở quá khứ hoàn thành." },
  { id: "c097", question: "Provided that the weather _____ fine, the match will go ahead.", options: ["remains", "remained", "will remain", "would remain"], correctIndex: 0, explanation: "'Provided that' + hiện tại đơn là câu điều kiện loại 1 ở văn phong trang trọng: provided that + hiện tại đơn, + will + V. Thời tiết đẹp là điều kiện thực tế có thể xảy ra để trận đấu diễn ra, nên chia 'remains' (hiện tại đơn, hòa hợp với 'the weather' số ít). 'Will remain' sai vì mệnh đề điều kiện (dù bắt đầu bằng 'provided that' thay vì 'if') vẫn không bao giờ dùng 'will'." },
  { id: "c098", question: "I'd rather you _____ told me the truth from the start.", options: ["have", "had", "would have", "will have"], correctIndex: 1, explanation: "Cấu trúc 'I'd rather + chủ ngữ khác + had + V3' dùng để bày tỏ sự hối tiếc về hành động của người khác trong quá khứ - ở đây là ước người kia đã nói thật ngay từ đầu. Đây là dạng nâng cao của 'I'd rather', tương tự tinh thần câu điều kiện loại 3 khi nói về quá khứ đã qua. 'Would have' sai vì sau 'I'd rather + chủ ngữ khác' khi nói về quá khứ, ta dùng 'had + V3' chứ không phải 'would have + V3'." },
  { id: "c099", question: "It's about time you _____ your own place.", options: ["get", "got", "will get", "have got"], correctIndex: 1, explanation: "'It's about time' + quá khứ đơn (got) là biến thể của 'it's time', diễn tả một việc đáng lẽ đã nên xảy ra rồi - ở đây là đã nên có nhà riêng từ trước. Cấu trúc này luôn dùng quá khứ đơn giả định dù đang nói về hiện tại/tương lai. 'Will get' sai vì 'it's (about) time' không bao giờ đi với 'will', chỉ dùng dạng quá khứ đơn đặc biệt này." },
  { id: "c100", question: "If you _____ the noise, wear earplugs.", options: ["can't stand", "couldn't stand", "won't stand", "wouldn't stand"], correctIndex: 0, explanation: "Câu điều kiện loại 1 với lời khuyên: If + hiện tại đơn (can't stand), + imperative (wear earplugs). Việc không chịu được tiếng ồn là một tình huống thực tế có thể đang xảy ra, nên mệnh đề 'if' chia ở hiện tại. 'Couldn't stand' sai vì đó là dạng quá khứ dùng cho giả định loại 2, không phù hợp với lời khuyên thiết thực áp dụng ngay cho hiện tại như câu này." },
  { id: "c101", question: "She _____ accepted if she applies early.", options: ["will be", "would be", "is", "was"], correctIndex: 0, explanation: "Câu điều kiện loại 1 ở thể bị động: If + hiện tại đơn (applies), + will be + V3 (will be accepted). Nộp đơn sớm là một hành động thực tế có thể thực hiện, dẫn đến khả năng được chấp nhận trong tương lai. 'Would be' sai vì mệnh đề 'if' đã chia hiện tại đơn 'applies' (đặc trưng của loại 1), không khớp với 'would' (đặc trưng của loại 2)." },
  { id: "c102", question: "If he hadn't been rude, he _____ fired.", options: ["won't be", "wouldn't be", "wouldn't have been", "won't have been"], correctIndex: 2, explanation: "Câu điều kiện loại 3 ở thể bị động: If + hadn't been (quá khứ hoàn thành), + wouldn't have been + V3 (wouldn't have been fired). Anh ta đã thô lỗ và thực tế đã bị sa thải, đây là giả định về một kết quả khác đáng lẽ đã xảy ra trong quá khứ. 'Wouldn't be' thiếu 'have' nên sai - đó là công thức của loại 2, không khớp với mệnh đề 'if' đã ở quá khứ hoàn thành." },
  { id: "c103", question: "Unless you _____ up, I won't help you.", options: ["show", "showed", "will show", "would show"], correctIndex: 0, explanation: "'Unless' + hiện tại đơn là câu điều kiện loại 1: câu này nghĩa là 'Nếu bạn không xuất hiện, tôi sẽ không giúp bạn'. Việc xuất hiện là điều kiện thực tế có thể xảy ra ngay, nên chia hiện tại đơn 'show'. 'Will show' sai vì giống mọi mệnh đề bắt đầu bằng liên từ điều kiện, phần sau 'unless' không bao giờ dùng 'will'." },
  { id: "c104", question: "If all goes well, we _____ finish by 6 PM.", options: ["should", "would", "will", "could"], correctIndex: 0, explanation: "Câu điều kiện loại 1: If + hiện tại đơn (goes), + should + V. 'Should' ở đây mang nghĩa dự đoán/kỳ vọng có căn cứ (chắc là sẽ xong), một biến thể của 'will' vẫn thuộc công thức loại 1. Mọi thứ diễn ra suôn sẻ là điều kiện thực tế có thể xảy ra, không phải giả định xa vời nên không chọn 'would' - từ đó chỉ dùng khi mệnh đề 'if' chia quá khứ đơn (loại 2), không khớp với 'goes' ở đây." },
  { id: "c105", question: "She wished she _____ a better job at the time.", options: ["has", "had", "had had", "would have"], correctIndex: 2, explanation: "'Wished' + quá khứ hoàn thành (had had) dùng để diễn tả sự hối tiếc về quá khứ, và khi động từ chính vốn là 'have/has' (have a job), nó phải lùi hai lần thành 'had had' khi 'wish' cũng ở thì quá khứ. Cụm 'at the time' xác nhận đây là hối tiếc về một thời điểm cụ thể trong quá khứ. 'Had' (chỉ một từ) là chưa đủ vì động từ gốc của câu là 'have' (have a job), nên phải chia thành 'had had', không phải chỉ 'had'." },
  { id: "c106", question: "If you heat it too long, it _____ sticky.", options: ["becomes", "become", "will become", "would become"], correctIndex: 0, explanation: "Câu điều kiện loại 0 diễn tả một sự thật/quy luật luôn đúng: If + hiện tại đơn, + hiện tại đơn. Đun quá lâu thì chất đó luôn trở nên dính, đây là hiện tượng lặp lại có thể kiểm chứng, không phải một dự đoán đơn lẻ, nên chia hiện tại đơn 'becomes' (hòa hợp với 'it'). 'Will become' là lỗi thường gặp - loại 0 không dùng 'will' vì đang nói về quy luật chung chứ không phải một sự việc cụ thể trong tương lai." },
  { id: "c107", question: "What _____ if you mixed those two chemicals?", options: ["happens", "will happen", "would happen", "happened"], correctIndex: 2, explanation: "Câu hỏi ở câu điều kiện loại 2: What would happen if + quá khứ đơn (mixed)? Đây là một câu hỏi giả định mang tính lý thuyết về một tình huống không thực sự đang xảy ra, nên vế chính dùng 'would'. 'Will happen' sai vì không khớp thì với 'mixed' ở mệnh đề 'if' - will chỉ đi cùng if + hiện tại đơn (loại 1), không phải quá khứ đơn." },
  { id: "c108", question: "If only he _____ the appointment — it could have changed his life.", options: ["keeps", "kept", "had kept", "would keep"], correctIndex: 2, explanation: "'If only' + quá khứ hoàn thành (had kept) dùng để hối tiếc về một việc đã không làm trong quá khứ - ở đây là đã không giữ cuộc hẹn. Vế sau 'it could have changed his life' (could have + V3) xác nhận đây là chuyện đã qua, không thể thay đổi. 'Kept' (quá khứ đơn) sai vì chỉ dùng cho ước muốn ở hiện tại, không khớp với 'could have changed' ở vế sau vốn nói về quá khứ." },
  { id: "c109", question: "I'd rather she _____ a different approach.", options: ["takes", "took", "will take", "would take"], correctIndex: 1, explanation: "Cấu trúc 'I'd rather + chủ ngữ khác + quá khứ đơn' dùng để bày tỏ mong muốn về hành động của người khác ở hiện tại/tương lai. Người nói muốn cô ấy áp dụng cách tiếp cận khác nên dùng 'took' dù đang nói về hiện tại. 'Takes' (hiện tại đơn) sai vì cấu trúc này luôn đòi hỏi động từ lùi về quá khứ đơn giả định, bất kể ý nghĩa thời gian thực sự." },
  { id: "c110", question: "_____ it not been for the rain, the festival would have been perfect.", options: ["If", "Had", "Were", "Should"], correctIndex: 1, explanation: "Đảo ngữ của cấu trúc 'If it hadn't been for the rain': 'Had it not been for the rain' = 'If it hadn't been for the rain' (nếu không vì trời mưa). Đây là đảo ngữ trang trọng của câu điều kiện loại 3, và vế chính 'would have been' xác nhận điều đó. 'Were' chỉ dùng để đảo ngữ loại 2, không khớp với vế kết quả có 'have been' ở đây." },
  { id: "c111", question: "She could get the promotion _____ she demonstrates leadership skills.", options: ["if", "unless", "although", "despite"], correctIndex: 0, explanation: "Câu điều kiện loại 1: if + hiện tại đơn (demonstrates), + could + V (could get). Thể hiện kỹ năng lãnh đạo là điều kiện thực tế có thể đạt được, dẫn đến khả năng được thăng chức, nên dùng 'if' để nối quan hệ nhân quả thuận. 'Unless' sẽ đổi nghĩa thành điều kiện phủ định (trừ khi cô ấy thể hiện... - không hợp lý ở đây); 'although/despite' chỉ diễn tả sự tương phản, không phải điều kiện." },
  { id: "c112", question: "If he _____ more polite, people would like him more.", options: ["is", "was", "were", "has been"], correctIndex: 2, explanation: "Câu điều kiện loại 2: If he were + tính từ (more polite), + would + V (would like). Đây là giả định trái thực tế ở hiện tại - anh ấy hiện không đủ lịch sự. Theo quy tắc chia to be ở câu điều kiện loại 2, 'were' được dùng cho mọi chủ ngữ và được ưu tiên trong văn viết chuẩn mực hơn 'was', dù cả hai đều được nghe thấy trong giao tiếp." },
  { id: "c113", question: "She would have called if she _____ your number.", options: ["has", "had", "knew", "had known"], correctIndex: 3, explanation: "Câu điều kiện loại 3: If + had known (quá khứ hoàn thành), + would have + V3 (would have called). Vế chính 'would have called' xác nhận công thức loại 3, nói về việc cô ấy đã không có số điện thoại nên đã không gọi. 'Knew' (quá khứ đơn) là bẫy hay gặp vì đúng ngữ pháp cho loại 2, nhưng ở đây không khớp với 'would have called' vốn đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành." },
  { id: "c114", question: "We'll go to the beach _____ it doesn't rain.", options: ["unless", "if", "provided that", "in case"], correctIndex: 2, explanation: "'Provided that' + hiện tại đơn phủ định (doesn't rain) là câu điều kiện loại 1 ở văn phong trang trọng, nhấn mạnh điều kiện cần thiết để đi biển. Cả 'if' và 'provided that' đều đúng ngữ pháp, nhưng ngữ cảnh này (một kế hoạch có điều kiện ràng buộc) phù hợp với sắc thái 'miễn là' của 'provided that' hơn. 'Unless' sẽ tạo ra ý nghĩa phủ định kép khó hiểu khi kết hợp với 'doesn't rain' đã có sẵn phủ định." },
  { id: "c115", question: "If you _____ that switch, the light goes off automatically.", options: ["press", "pressed", "will press", "have pressed"], correctIndex: 0, explanation: "Câu điều kiện loại 0 (thực tế/quy luật máy móc): If + hiện tại đơn, + hiện tại đơn. Bấm công tắc này thì đèn luôn tự động tắt, đây là một cơ chế cố định chứ không phải một khả năng, nên chia 'press' ở hiện tại đơn. 'Will press' sai vì loại 0 không dùng 'will' - dấu hiệu nhận biết là cả hai mệnh đề đều ở hiện tại đơn." },
  { id: "c116", question: "I'd rather _____ at home tonight.", options: ["stayed", "stay", "to stay", "staying"], correctIndex: 1, explanation: "Khi 'I'd rather' không có chủ ngữ thứ hai (chỉ hành động của chính người nói), động từ theo sau dùng nguyên thể không 'to' (bare infinitive) - ở đây là 'stay'. Đây là điểm khác với trường hợp có chủ ngữ khác (khi đó phải chia quá khứ đơn, như 'I'd rather you stayed'). 'Stayed' sai trong trường hợp này vì không có chủ ngữ thứ hai để cần dạng quá khứ giả định, còn 'to stay/staying' sai vì cấu trúc này không đi với to-infinitive hay V-ing." },
  { id: "c117", question: "If she _____ the news, she would have been devastated.", options: ["hears", "heard", "had heard", "would hear"], correctIndex: 2, explanation: "Câu điều kiện loại 3: If + had heard (quá khứ hoàn thành), + would have + V3 (would have been devastated). Câu diễn tả một cảm xúc giả định trong quá khứ - nếu cô ấy đã nghe tin đó (nhưng thực tế đã không nghe) thì đã suy sụp. 'Heard' (quá khứ đơn) sai vì vế chính đã dùng 'would have been' (loại 3), đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành." },
  { id: "c118", question: "It's time the government _____ something about pollution.", options: ["does", "did", "will do", "would do"], correctIndex: 1, explanation: "'It's time' + quá khứ đơn (did) diễn tả một việc chính phủ đáng lẽ nên làm rồi nhưng đến giờ vẫn chưa làm - đây là cách phê phán/thúc giục nhẹ nhàng bằng ngữ pháp. Dù đang nói về hành động cần thực hiện trong hiện tại/tương lai, cấu trúc 'it's time' luôn dùng quá khứ đơn giả định. 'Will do' sai vì cấu trúc này không bao giờ dùng 'will', chỉ dùng quá khứ đơn đặc biệt." },
  { id: "c119", question: "She might _____ the contract if you had offered better terms.", options: ["sign", "signed", "have signed", "be signing"], correctIndex: 2, explanation: "Câu điều kiện loại 3: mệnh đề 'if' đã chia 'had offered' (quá khứ hoàn thành) nên vế chính cần 'might have + V3' (might have signed) để diễn tả một khả năng đã có thể xảy ra nhưng thực tế đã không xảy ra. Điều kiện về mức lương tốt hơn đã không được đưa ra nên hợp đồng đã không được ký. 'Signed' thiếu 'have' nên sai - không tạo đúng cụm động từ hoàn thành cần có ở loại 3." },
  { id: "c120", question: "If he _____ properly, he could have won the race.", options: ["trains", "trained", "had trained", "would train"], correctIndex: 2, explanation: "Câu điều kiện loại 3: If + had trained (quá khứ hoàn thành), + could have + V3 (could have won). Việc luyện tập đúng cách đã không xảy ra trong quá khứ nên anh ấy đã không thắng cuộc đua - một cơ hội đã bị bỏ lỡ. 'Trained' (quá khứ đơn) sai vì vế chính 'could have won' (loại 3) đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành, không phải quá khứ đơn của loại 2." },
  { id: "c121", question: "I'll do it _____ you ask me nicely.", options: ["as long as", "unless", "even if", "in spite of"], correctIndex: 0, explanation: "'As long as' + hiện tại đơn (ask) là câu điều kiện loại 1, diễn tả một điều kiện cần thiết để hành động xảy ra - ở đây là sẽ làm nếu được nhờ một cách lịch sự. 'Even if' sẽ mang nghĩa khác (dù bạn có nhờ lịch sự hay không, tôi vẫn làm) - không khớp với ý câu muốn nhấn mạnh điều kiện. 'In spite of' theo sau phải là danh từ/cụm danh từ, không thể theo sau bởi cả một mệnh đề như thế này." },
  { id: "c122", question: "If she _____ the truth, she wouldn't be in trouble now.", options: ["tells", "told", "had told", "would tell"], correctIndex: 2, explanation: "Câu điều kiện hỗn hợp: điều kiện thuộc về quá khứ (nói sự thật là chuyện đáng lẽ đã làm trước đây) nên mệnh đề 'if' chia quá khứ hoàn thành 'had told', nhưng kết quả ảnh hưởng đến hiện tại (thể hiện qua từ 'now') nên vế chính chỉ cần 'wouldn't be' chứ không phải 'wouldn't have been'. Đây là dấu hiệu nhận biết câu hỗn hợp: chú ý từ 'now' ở vế kết quả. 'Told' (quá khứ đơn) sai vì không đủ diễn tả một hành động đã hoàn toàn kết thúc trong quá khứ như 'had told'." },
  { id: "c123", question: "He acts as though he _____ everything.", options: ["knows", "knew", "had known", "would know"], correctIndex: 1, explanation: "'As though/as if' + quá khứ đơn dùng để so sánh với một điều không có thật ở hiện tại - thực tế anh ta không biết hết mọi thứ nhưng hành xử như thể biết. Cấu trúc này giống tinh thần câu điều kiện loại 2 (giả định trái thực tế ở hiện tại). 'Knows' (hiện tại đơn) sai vì nếu dùng hiện tại đơn, câu sẽ ngụ ý điều đó có thể là sự thật, trong khi 'as if/as though' + quá khứ đơn mới đúng để nhấn mạnh tính giả tạo, không có thật." },
  { id: "c124", question: "She talks as if she _____ the boss.", options: ["is", "was", "were", "has been"], correctIndex: 2, explanation: "'As if' + were (hình thức giả định của to be, dùng cho mọi chủ ngữ) để so sánh với một thực tế không đúng - cô ấy nói chuyện như thể là sếp nhưng thực ra không phải. Đây là quy tắc giống câu điều kiện loại 2: to be sau 'as if/as though' luôn ưu tiên 'were'. 'Was' vẫn được dùng trong văn nói thân mật nhưng 'were' là lựa chọn chuẩn mực hơn, đặc biệt khi nhấn mạnh tính phi thực tế." },
  { id: "c125", question: "He looked as if he _____ a ghost.", options: ["sees", "saw", "had seen", "would see"], correctIndex: 2, explanation: "'As if' + quá khứ đơn (saw) dùng để so sánh với một trạng thái không có thật ở hiện tại/thời điểm được nói đến - trông anh ta như thể (nhưng thực ra không) nhìn thấy ma. Đây là cách diễn đạt giả định tại chính thời điểm đang miêu tả, không phải trước đó, nên dùng quá khứ đơn chứ không phải quá khứ hoàn thành. 'Had seen' sẽ ngụ ý việc nhìn thấy xảy ra trước thời điểm 'looked', khác với ý câu muốn diễn tả (biểu cảm sợ hãi ngay lúc đó)." },
  { id: "c126", question: "If I _____ you to keep a secret, would you?", options: ["ask", "asked", "had asked", "am asking"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If I asked (quá khứ đơn), + would you (would + V)? Đây là một tình huống giả định, hỏi ý kiến về một việc chưa xảy ra và chưa chắc sẽ xảy ra. Vế chính 'would you' xác nhận công thức loại 2 nên mệnh đề 'if' phải chia quá khứ đơn 'asked'. 'Ask' (hiện tại đơn) sai vì không khớp thì với 'would' - would chỉ đi cùng if + quá khứ đơn." },
  { id: "c127", question: "_____ you require any further assistance, please contact us.", options: ["If", "Should", "Were", "Had"], correctIndex: 1, explanation: "Đảo ngữ trang trọng của câu điều kiện loại 1: 'Should you require' = 'If you should require' (nếu như bạn cần thêm hỗ trợ). Cách nói này thường gặp trong email/văn bản trang trọng để nhấn mạnh khả năng có thể xảy ra trong tương lai một cách lịch sự. 'Were' và 'Had' là đảo ngữ của loại 2 và loại 3, không phù hợp với ngữ cảnh dịch vụ khách hàng mang tính hiện tại/tương lai như câu này." },
  { id: "c128", question: "If dogs _____ talk, what do you think they would say?", options: ["can", "could", "would", "should"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + could (quá khứ đơn của can), + would + V (would say). Chó không thể nói chuyện nên đây là một giả định hoàn toàn phi thực tế mang tính vui đùa, tưởng tượng. Vế sau 'would say' xác nhận công thức loại 2 nên 'if' phải chia 'could' chứ không phải 'can' (hiện tại đơn, chỉ dùng cho loại 0 hoặc loại 1)." },
  { id: "c129", question: "Even if I _____ the money, I wouldn't buy that car.", options: ["have", "had", "will have", "would have"], correctIndex: 1, explanation: "'Even if' + quá khứ đơn (had) là câu điều kiện loại 2, nhấn mạnh rằng dù có tiền đi nữa (một giả định) thì người nói vẫn sẽ không mua chiếc xe đó. Vế chính 'wouldn't buy' xác nhận công thức loại 2. 'Have' (hiện tại đơn) sai vì không khớp thì với 'wouldn't' ở vế chính - would luôn đòi hỏi mệnh đề điều kiện ở quá khứ đơn." },
  { id: "c130", question: "If I _____ the chance to relive my life, I'd do many things differently.", options: ["have", "had", "will have", "would have"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (had), + 'd (would) + V. Được sống lại cuộc đời là một giả định hoàn toàn không có thật, mang tính suy ngẫm/tưởng tượng. 'Will have' sai vì đây không phải một khả năng thực tế trong tương lai (loại 1) mà là một giả định trái thực tế, đòi hỏi 'would' ở vế chính và 'had' ở mệnh đề 'if'." },
  { id: "c131", question: "She'll be angry _____ you don't call her back.", options: ["if", "unless", "provided", "as long as"], correctIndex: 0, explanation: "Câu điều kiện loại 1: if + hiện tại đơn phủ định (don't call), + will + V (she'll be). Việc không gọi lại là điều kiện thực tế có thể dẫn đến sự tức giận, nên dùng 'if' để nối quan hệ nhân quả thuận. 'Unless' sẽ tạo ra phủ định kép khó hiểu khi kết hợp với 'don't call' đã có sẵn phủ định trong câu." },
  { id: "c132", question: "If the project _____ on budget, the client will be happy.", options: ["comes", "came", "will come", "would come"], correctIndex: 0, explanation: "Câu điều kiện loại 1: If + hiện tại đơn (comes), + will + V (will be). Dự án hoàn thành đúng ngân sách là điều kiện thực tế có khả năng xảy ra, nên mệnh đề 'if' chia hiện tại đơn. 'Will come' sai vì mệnh đề 'if' không bao giờ dùng 'will', dù cả câu đang bàn về một sự việc trong tương lai." },
  { id: "c133", question: "I wish she _____ interrupting me all the time!", options: ["stops", "stopped", "would stop", "had stopped"], correctIndex: 2, explanation: "'Wish' + would stop dùng để phàn nàn, mong muốn ai đó (khác với người nói) thay đổi một hành vi gây phiền toái đang lặp lại - ở đây là bị ngắt lời liên tục. Đây là cách dùng đặc biệt của 'wish' khác với ước về trạng thái (dùng quá khứ đơn) hay hối tiếc quá khứ (dùng quá khứ hoàn thành). 'Stopped' sai vì đó là ước về một trạng thái tĩnh, trong khi câu này đang phàn nàn về một hành động lặp đi lặp lại gây khó chịu, cần 'would + V'." },
  { id: "c134", question: "If he _____ more careful with money, he wouldn't be in debt.", options: ["is", "was", "were", "has been"], correctIndex: 2, explanation: "Câu điều kiện loại 2: If he were + tính từ (more careful), + wouldn't be (would not be). Thực tế anh ấy không cẩn thận với tiền bạc nên đang nợ nần - một giả định trái ngược với hiện tại. Theo quy tắc chia to be ở loại 2, 'were' áp dụng cho mọi chủ ngữ và là lựa chọn chuẩn mực hơn 'was' trong ngữ pháp trang trọng." },
  { id: "c135", question: "We could have avoided the problem _____ acted sooner.", options: ["if we", "had we", "we had", "if had we"], correctIndex: 1, explanation: "Đảo ngữ câu điều kiện loại 3: 'had we acted sooner' = 'if we had acted sooner', đảo trợ động từ 'had' lên trước chủ ngữ 'we' và bỏ 'if'. Vế chính 'could have avoided' xác nhận đây là loại 3, nói về một cơ hội đã bị bỏ lỡ trong quá khứ. 'If had we' sai về trật tự từ - khi đảo ngữ, 'if' phải được lược bỏ hoàn toàn, không thể giữ cả 'if' lẫn đảo trợ động từ." },
  { id: "c136", question: "If you _____ earlier, you would have gotten a seat.", options: ["come", "came", "had come", "would come"], correctIndex: 2, explanation: "Câu điều kiện loại 3: If + had come (quá khứ hoàn thành), + would have + V3 (would have gotten). Việc đến sớm hơn đã không xảy ra trong quá khứ nên đã không có chỗ ngồi. 'Came' (quá khứ đơn) sai vì vế chính 'would have gotten' (loại 3) đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành, không phải quá khứ đơn của loại 2." },
  { id: "c137", question: "I'd rather you _____ me before making that decision.", options: ["ask", "asked", "had asked", "would ask"], correctIndex: 2, explanation: "Cấu trúc 'I'd rather + chủ ngữ khác + had + V3' dùng để hối tiếc về hành động của người khác trong quá khứ - ở đây là ước người kia đã hỏi ý kiến trước khi quyết định (nhưng thực tế đã không hỏi). Vì hành động 'making that decision' đã xảy ra rồi, cần dùng quá khứ hoàn thành để nói về việc đáng lẽ nên xảy ra trước đó. 'Asked' (chỉ quá khứ đơn) sai vì không đủ để diễn tả một điều đáng lẽ đã xảy ra trước một mốc thời gian khác trong quá khứ." },
  { id: "c138", question: "Unless there _____ a significant improvement, we'll have to terminate the contract.", options: ["is", "are", "was", "were"], correctIndex: 0, explanation: "'Unless' + hiện tại đơn (câu điều kiện loại 1): unless there is = if there isn't. Với cấu trúc 'there is/are', vì 'improvement' là danh từ số ít nên chia 'is'. 'Was/were' sai vì đây là một khả năng thực tế có thể xảy ra trong tương lai gần (loại 1), không phải giả định phi thực tế (loại 2) nên không dùng quá khứ đơn." },
  { id: "c139", question: "She _____ to be a doctor if she hadn't been afraid of blood.", options: ["trains", "trained", "would have trained", "would train"], correctIndex: 3, explanation: "Câu điều kiện hỗn hợp: điều kiện thuộc về quá khứ (hadn't been afraid - quá khứ hoàn thành) nhưng kết quả là một mong muốn/xu hướng vẫn còn đúng ở hiện tại (cô ấy vẫn đang có khả năng theo đuổi việc trở thành bác sĩ), nên vế chính dùng 'would train' chứ không phải 'would have trained'. Đây là dạng hỗn hợp ít gặp hơn: nguyên nhân quá khứ ảnh hưởng đến một trạng thái/xu hướng kéo dài đến hiện tại. 'Would have trained' sẽ ngụ ý việc đó đã hoàn toàn kết thúc trong quá khứ, không còn liên quan đến hiện tại như ngữ cảnh câu muốn nói." },
  { id: "c140", question: "If I _____ you, I would have taken the offer.", options: ["am", "was", "were", "had been"], correctIndex: 3, explanation: "Khi tư vấn về một quyết định đã xảy ra trong quá khứ (không phải lời khuyên chung như 'If I were you'), câu điều kiện chuyển sang loại 3: If + had been, + would have + V3. Vế chính 'would have taken' xác nhận đây là loại 3, nói về một cơ hội trong quá khứ. Đừng nhầm với cấu trúc quen thuộc 'If I were you' (loại 2, lời khuyên chung) - khi vế chính đã ở dạng 'would have taken' (nói về việc cụ thể đã qua), phải dùng 'had been' chứ không phải 'were'." },
  { id: "c141", question: "What _____ you do if someone insulted you publicly?", options: ["do", "will", "would", "did"], correctIndex: 2, explanation: "Câu hỏi ở câu điều kiện loại 2: What would you do if + quá khứ đơn (insulted)? Đây là câu hỏi về một tình huống giả định, mang tính lý thuyết chứ không phải một khả năng thực tế đang chờ xảy ra. 'Will' sai vì không khớp thì với 'insulted' (quá khứ đơn) ở mệnh đề 'if' - will chỉ đi cùng if + hiện tại đơn của loại 1." },
  { id: "c142", question: "You _____ get in free if you have a student card.", options: ["can", "could", "might", "will"], correctIndex: 0, explanation: "Câu điều kiện loại 1 mang nghĩa cho phép: If + hiện tại đơn (have), + can + V. Có thẻ sinh viên là điều kiện thực tế, rõ ràng để được vào cửa miễn phí, nên 'can' phù hợp nhất để diễn tả quyền được phép này. 'Could' mang sắc thái giả định hoặc lịch sự hơn, không phù hợp bằng 'can' khi nói về một quy định/quyền lợi cụ thể, rõ ràng như thế này." },
  { id: "c143", question: "If she _____ the email, she would have replied by now.", options: ["receives", "received", "has received", "had received"], correctIndex: 3, explanation: "Câu điều kiện loại 3: If + had received (quá khứ hoàn thành), + would have + V3 (would have replied). Việc nhận được email đã không xảy ra nên cô ấy đã không trả lời - dù có cụm 'by now' ở cuối, đây vẫn là loại 3 chuẩn vì cả điều kiện lẫn kết quả đều nói về một chuỗi sự kiện đã hoàn toàn thuộc về quá khứ. 'Received' (quá khứ đơn) sai vì vế chính 'would have replied' đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành." },
  { id: "c144", question: "He speaks as though he _____ an expert, but he's just a student.", options: ["is", "was", "were", "has been"], correctIndex: 2, explanation: "'As though' + were dùng để so sánh với một tình huống không có thật ở hiện tại - anh ta nói như thể là chuyên gia nhưng thực ra chỉ là sinh viên (được xác nhận ngay trong câu). Đây là quy tắc giống câu điều kiện loại 2: to be sau 'as though/as if' ưu tiên dùng 'were' cho mọi chủ ngữ để nhấn mạnh tính phi thực tế. 'Is' sai vì sẽ ngụ ý điều đó có thể đúng, mâu thuẫn với thông tin 'he's just a student' ngay sau đó." },
  { id: "c145", question: "If only I _____ what I know now back then!", options: ["know", "knew", "had known", "would know"], correctIndex: 2, explanation: "'If only' + quá khứ hoàn thành (had known) dùng để hối tiếc sâu sắc về một điều đã không biết trong quá khứ. Cụm 'back then' đối lập với 'now' cho thấy rõ đây là tiếc nuối về quá khứ, không phải hiện tại. 'Knew' (quá khứ đơn) sai vì chỉ phù hợp khi ước về hiện tại, trong khi câu này rõ ràng đang so sánh kiến thức hiện tại với sự thiếu hiểu biết trong quá khứ." },
  { id: "c146", question: "It's time you _____ responsibility for your actions.", options: ["take", "took", "will take", "have taken"], correctIndex: 1, explanation: "'It's time' + quá khứ đơn (took) diễn tả điều đáng lẽ nên làm ngay bây giờ - đã đến lúc phải có trách nhiệm với hành động của mình. Đây là cấu trúc cố định luôn dùng quá khứ đơn giả định dù nói về hiện tại/tương lai. 'Will take' sai vì cấu trúc 'it's time' không bao giờ dùng 'will'." },
  { id: "c147", question: "We wouldn't be lost if you _____ the map.", options: ["consult", "consulted", "had consulted", "would consult"], correctIndex: 2, explanation: "Đây là câu điều kiện hỗn hợp: điều kiện ở quá khứ (đã không xem bản đồ) dẫn đến kết quả ở hiện tại (đang bị lạc - 'wouldn't be lost', không có 'have'), nên mệnh đề 'if' chia quá khứ hoàn thành 'had consulted' còn vế chính giữ nguyên 'would be' (không thêm have). 'Consulted' (quá khứ đơn) sai vì không đủ diễn tả một hành động đáng lẽ đã hoàn thành trong quá khứ để gây ra tình trạng hiện tại; cần phân biệt với 'would have consulted' vốn không xuất hiện ở đây." },
  { id: "c148", question: "She'll get a good grade _____ she puts in the effort.", options: ["unless", "as long as", "even if", "in case"], correctIndex: 1, explanation: "'As long as' + hiện tại đơn (puts) là câu điều kiện loại 1, diễn tả điều kiện cần thiết để đạt kết quả tốt - cố gắng là điều kiện để có điểm cao. 'Even if' sẽ đổi nghĩa (dù có cố gắng hay không cũng đạt điểm tốt - không hợp lý); 'unless' tạo nghĩa phủ định không phù hợp với mối quan hệ nhân quả thuận trong câu." },
  { id: "c149", question: "If I _____ the chance again, I'd do it differently.", options: ["get", "got", "had gotten", "would get"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (got), + 'd (would) + V. Đây là một giả định về việc có lại cơ hội - một điều không chắc chắn xảy ra ở hiện tại/tương lai. 'Had gotten' sai vì đó là quá khứ hoàn thành (loại 3), trong khi vế chính chỉ có 'I'd do' (would do, không có 'have'), xác nhận đây là loại 2 chứ không phải loại 3." },
  { id: "c150", question: "_____ you to change your mind, let me know immediately.", options: ["If", "Should", "Were", "Had"], correctIndex: 2, explanation: "Đảo ngữ trang trọng của câu điều kiện loại 2 với cấu trúc 'were to': 'Were you to change your mind' = 'If you were to change your mind' (nếu như bạn đổi ý). Cấu trúc 'were to' thường dùng để nói về một khả năng ít chắc chắn trong tương lai theo cách trang trọng. 'Should' dùng để đảo ngữ cho loại 1 (khả năng thực tế hơn), không phù hợp bằng 'were to' khi muốn nhấn mạnh tính giả định của việc đổi ý." },
  { id: "c151", question: "If he _____ the truth, I would never have trusted him.", options: ["hid", "hides", "had hidden", "would hide"], correctIndex: 2, explanation: "Câu điều kiện loại 3: If + had hidden (quá khứ hoàn thành), + would have + V3 (would never have trusted). Việc giấu sự thật là một hành động đã xảy ra và đã ảnh hưởng đến lòng tin trong quá khứ. 'Hid' (quá khứ đơn) sai vì vế chính 'would never have trusted' (loại 3) đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành, không phải quá khứ đơn." },
  { id: "c152", question: "What would you do if you _____ the last person on earth?", options: ["are", "were", "had been", "will be"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + were (quá khứ đơn của to be), + would + V. Là người cuối cùng trên trái đất là một giả định hoàn toàn viễn tưởng, không có thật, nên chia 'were' theo quy tắc của to be trong loại 2. 'Are' (hiện tại đơn) sai vì không khớp thì với 'would' ở vế chính." },
  { id: "c153", question: "If you mix red and yellow, you _____ orange.", options: ["get", "got", "will get", "would get"], correctIndex: 0, explanation: "Câu điều kiện loại 0 diễn tả một sự thật hiển nhiên về màu sắc: If + hiện tại đơn, + hiện tại đơn. Pha đỏ và vàng luôn cho ra màu cam, đây là quy luật không đổi (giống nguyên lý pha màu), không phụ thuộc thời điểm nên chia 'get' ở hiện tại đơn. 'Will get' sai vì loại 0 không dùng 'will' - đây không phải một dự đoán mà là một kết quả chắc chắn, luôn đúng." },
  { id: "c154", question: "She'd have stayed longer _____ she hadn't had a flight to catch.", options: ["if", "unless", "although", "in case"], correctIndex: 0, explanation: "Câu điều kiện loại 3: if + hadn't had (quá khứ hoàn thành phủ định), + would have + V3 ('she'd have stayed' = she would have stayed). Câu diễn tả một kết quả khác đáng lẽ đã xảy ra nếu không có chuyến bay phải bắt - một sự kiện đã kết thúc trong quá khứ. 'Unless' sẽ tạo phủ định kép rối nghĩa khi kết hợp với 'hadn't had' đã có sẵn phủ định." },
  { id: "c155", question: "Unless we _____ now, we'll miss the opening ceremony.", options: ["leave", "left", "will leave", "would leave"], correctIndex: 0, explanation: "'Unless' + hiện tại đơn (leave) là câu điều kiện loại 1: unless we leave now = if we don't leave now. Rời đi ngay bây giờ là một hành động hoàn toàn khả thi trong hiện tại, dẫn đến việc tránh lỡ buổi khai mạc. 'Will leave' sai vì phần sau 'unless' cũng tuân theo quy tắc như 'if' - không bao giờ dùng 'will' trong mệnh đề điều kiện." },
  { id: "c156", question: "If there _____ a problem, press the red button.", options: ["is", "was", "were", "will be"], correctIndex: 0, explanation: "Câu điều kiện loại 1 dạng hướng dẫn: If + hiện tại đơn (is), + imperative (press). Việc có sự cố là một khả năng thực tế có thể xảy ra bất cứ lúc nào, và hướng dẫn xử lý được đưa ra bằng câu mệnh lệnh thay vì 'will'. 'Was/were' sai vì đó là công thức của loại 2, dùng cho giả định phi thực tế, không phù hợp với một bảng hướng dẫn sử dụng thực tế như câu này." },
  { id: "c157", question: "I'd rather _____ the meeting rescheduled.", options: ["have", "had", "to have", "having"], correctIndex: 0, explanation: "Cấu trúc 'I'd rather have + tân ngữ + V3' (ở đây là 'have the meeting rescheduled') dùng để diễn tả mong muốn một việc được thực hiện cho mình (dạng nhờ vả/gây khiến - causative), với 'have' ở dạng nguyên thể không 'to' theo sau 'rather'. 'Had' sai vì sẽ tạo thành hai động từ chia liên tiếp không hợp lý; 'to have/having' sai vì 'rather' luôn đòi hỏi động từ nguyên thể không 'to' theo ngay sau nó." },
  { id: "c158", question: "If only I _____ her name!", options: ["remember", "remembered", "could remember", "had remembered"], correctIndex: 2, explanation: "'If only' + could remember dùng để ước về một khả năng bị thiếu hụt ở hiện tại - người nói hiện không nhớ được tên cô ấy. 'Could' nhấn mạnh vào khả năng (không thể nhớ được), khác với 'remembered' đơn thuần chỉ là ước về hành động. 'Had remembered' sai vì đó là ước về quá khứ (đã không nhớ ra vào lúc nào đó), trong khi câu này đang nói về khả năng nhớ ngay ở hiện tại." },
  { id: "c159", question: "She _____ the deal if she hadn't pushed too hard.", options: ["closes", "closed", "might have closed", "would close"], correctIndex: 2, explanation: "Câu điều kiện loại 3: mệnh đề 'if' đã chia 'hadn't pushed' (quá khứ hoàn thành phủ định) nên vế chính cần 'might have + V3' (might have closed) để diễn tả một khả năng đã có thể xảy ra nhưng đã không xảy ra vì cô ấy đã gây áp lực quá mức. 'Would close' thiếu 'have' nên sai - không tạo đúng cụm động từ hoàn thành cần thiết ở loại 3." },
  { id: "c160", question: "If he were more ambitious, he _____ applied for the senior position.", options: ["would have", "could have", "would", "might"], correctIndex: 0, explanation: "Câu điều kiện hỗn hợp: điều kiện là một đặc điểm tính cách ở hiện tại (were more ambitious - quá khứ đơn) nhưng kết quả lại là một hành động đáng lẽ đã xảy ra trong quá khứ (applied for), nên vế chính dùng 'would have applied'. Đây là dạng hỗn hợp ngược với các câu trước: nguyên nhân hiện tại (tính cách) ảnh hưởng đến một cơ hội đã qua. 'Would' hoặc 'might' thiếu 'have' nên sai - không tạo được đúng cụm quá khứ hoàn thành để khớp với 'applied' (một hành động đã qua)." },
  { id: "c161", question: "She talked to him as if she _____ him for years, but they'd just met.", options: ["knows", "knew", "had known", "has known"], correctIndex: 2, explanation: "'As if' + quá khứ hoàn thành (had known) dùng để so sánh với một thực tế không đúng kéo dài về trước - cô ấy nói chuyện như thể đã quen biết anh ta từ lâu, nhưng thực ra họ mới gặp nhau (được xác nhận ngay sau đó). Vì hành động 'biết nhau nhiều năm' được so sánh xảy ra trước thời điểm 'talked', cần dùng quá khứ hoàn thành thay vì quá khứ đơn. 'Knew' (chỉ quá khứ đơn) sai vì không diễn tả được khoảng thời gian trước đó ('for years') mà câu muốn nhấn mạnh." },
  { id: "c162", question: "You can stay here _____ you keep quiet.", options: ["although", "as long as", "in case", "even if"], correctIndex: 1, explanation: "'As long as' + hiện tại đơn (keep) là câu điều kiện loại 1, diễn tả điều kiện cần thiết để được phép ở lại - giữ yên lặng là điều kiện. 'Although' chỉ diễn tả sự tương phản (mặc dù), không phải điều kiện; 'even if' sẽ đổi nghĩa thành 'dù có ồn ào hay không cũng được ở lại' - trái với ý câu muốn yêu cầu." },
  { id: "c163", question: "If I _____ in your position, I'd resign immediately.", options: ["am", "was", "were", "be"], correctIndex: 2, explanation: "Câu điều kiện loại 2: If I were in your position (giả định đặt mình vào hoàn cảnh người khác), + I'd (would) resign. Đây là một giả định phi thực tế - người nói không thực sự ở vị trí của người nghe. Theo quy tắc chia to be ở loại 2, 'were' luôn được ưu tiên hơn 'was' cho mọi chủ ngữ, đặc biệt trong cấu trúc lời khuyên tương tự 'If I were you'." },
  { id: "c164", question: "What would you say if someone _____ you an impossible task?", options: ["give", "gives", "gave", "had given"], correctIndex: 2, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (gave), + would + V (would say). Đây là câu hỏi giả định về một tình huống mang tính lý thuyết, không phải một khả năng cụ thể đang chờ xảy ra. 'Gives' (hiện tại đơn) sai vì không khớp thì với 'would say' ở vế chính - would luôn đòi hỏi mệnh đề 'if' ở quá khứ đơn." },
  { id: "c165", question: "She wishes she _____ the chance to study abroad.", options: ["has", "had had", "will have", "would have"], correctIndex: 1, explanation: "'Wish' + quá khứ hoàn thành (had had) dùng để hối tiếc về một cơ hội đã bỏ lỡ trong quá khứ - vì động từ gốc là 'have' (have the chance), khi lùi thì theo 'wish' nó trở thành 'had had'. Đây là điểm dễ nhầm: 'had' một mình không đủ khi động từ gốc vốn đã là 'have'. 'Has' (hiện tại đơn) sai vì rõ ràng câu đang nói về một cơ hội đã qua (du học), không phải điều đang thiếu ở hiện tại." },
  { id: "c166", question: "It's time the children _____ to bed.", options: ["go", "went", "will go", "should go"], correctIndex: 1, explanation: "'It's time' + quá khứ đơn (went) diễn tả điều nên xảy ra ngay bây giờ - đã đến giờ đi ngủ. Đây là cấu trúc cố định, luôn dùng quá khứ đơn giả định dù nói về hiện tại. 'Should go' tuy có nghĩa gần đúng nhưng sai cấu trúc - 'it's time' đòi hỏi quá khứ đơn thuần túy, không cần thêm động từ khiếm khuyết 'should'." },
  { id: "c167", question: "If you _____ comfortable, please take a seat.", options: ["felt", "feel", "will feel", "would feel"], correctIndex: 1, explanation: "Câu điều kiện loại 1 dạng mời mọc lịch sự: If + hiện tại đơn (feel), + imperative (please take a seat). Cảm thấy thoải mái là một trạng thái thực tế có thể đang diễn ra, và lời mời được đưa ra bằng câu cầu khiến. 'Felt' sai vì đó là quá khứ đơn (thuộc công thức loại 2), không phù hợp với một lời mời mang tính thực tế, tức thời như câu này." },
  { id: "c168", question: "He'd have been here sooner if the traffic _____ so bad.", options: ["isn't", "wasn't", "weren't", "hadn't been"], correctIndex: 3, explanation: "Câu điều kiện loại 3: If + hadn't been (quá khứ hoàn thành phủ định), + would have + V3 ('he'd have been' = he would have been). Giao thông thực tế đã tệ nên anh ấy đã đến muộn hơn dự kiến - một sự việc đã hoàn toàn xảy ra trong quá khứ. 'Weren't' (quá khứ đơn) sai vì vế chính 'would have been' (loại 3) đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành." },
  { id: "c169", question: "_____ I have any news, I'll contact you right away.", options: ["Unless", "Should", "Were", "Had"], correctIndex: 1, explanation: "Đảo ngữ trang trọng của câu điều kiện loại 1: 'Should I have any news' = 'If I should have any news' (nếu như tôi có tin gì mới). Cách nói này thường dùng trong giao tiếp công việc trang trọng để nói về một khả năng chưa chắc chắn trong tương lai. 'Were' và 'Had' là đảo ngữ của loại 2 và loại 3, không khớp với vế chính 'I'll contact' (will - loại 1)." },
  { id: "c170", question: "If she _____ to the gym regularly, she'd be much fitter.", options: ["goes", "went", "had gone", "would go"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (went), + 'd (would) + V (would be). Thực tế cô ấy không tập gym thường xuyên nên chưa đủ khỏe mạnh - một giả định trái với thực tế hiện tại. 'Had gone' sai vì đó là quá khứ hoàn thành (loại 3), trong khi vế chính chỉ có 'would be' (không có 'have'), xác nhận đây là loại 2." },
  { id: "c171", question: "I'd rather you _____ call me at this hour.", options: ["don't", "didn't", "won't", "wouldn't"], correctIndex: 1, explanation: "Cấu trúc 'I'd rather + chủ ngữ khác + quá khứ đơn phủ định' (didn't call) dùng để bày tỏ mong muốn người khác không làm gì đó - ở đây là không muốn bị gọi điện vào giờ này. 'Don't' (hiện tại đơn) sai vì cấu trúc 'I'd rather + chủ ngữ khác' luôn đòi hỏi động từ chia ở quá khứ đơn giả định, dù đang nói về hiện tại/tương lai." },
  { id: "c172", question: "If you _____ me, what would you do in this situation?", options: ["are", "were", "have been", "will be"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If you were me (giả định đổi vị trí, hoàn toàn phi thực tế), + what would you do? Vế chính 'would you do' xác nhận công thức loại 2 nên mệnh đề 'if' phải chia 'were' - quy tắc chuẩn cho to be trong câu điều kiện loại 2. 'Are' (hiện tại đơn) sai vì không khớp thì với 'would' ở vế chính." },
  { id: "c173", question: "Even if it _____ tomorrow, I'll still go for my run.", options: ["snows", "snowed", "will snow", "would snow"], correctIndex: 0, explanation: "'Even if' + hiện tại đơn (snows) là câu điều kiện loại 1, nhấn mạnh rằng dù điều kiện đó (tuyết rơi - một khả năng thực tế vào ngày mai) có xảy ra, kết quả vẫn không đổi. Vế chính 'I'll still go' (will) xác nhận công thức loại 1 nên mệnh đề với 'even if' cũng phải chia hiện tại đơn. 'Will snow' sai vì mệnh đề điều kiện (dù bắt đầu bằng 'even if') vẫn không bao giờ dùng 'will'." },
  { id: "c174", question: "She'd have told you if she _____ earlier.", options: ["knows", "knew", "had known", "would know"], correctIndex: 2, explanation: "Câu điều kiện loại 3: If + had known (quá khứ hoàn thành), + would have + V3 ('she'd have told' = she would have told). Việc biết sớm hơn đã không xảy ra trong quá khứ nên cô ấy đã không kể cho bạn biết. 'Knew' (quá khứ đơn) sai vì vế chính 'would have told' (loại 3) đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành." },
  { id: "c175", question: "If only he _____ his temper better!", options: ["controls", "controlled", "could control", "had controlled"], correctIndex: 2, explanation: "'If only' + could control dùng để ước về một khả năng bị thiếu hụt ở hiện tại - anh ấy hiện không kiểm soát được tính khí của mình tốt hơn. 'Could' nhấn mạnh vào năng lực làm chủ bản thân, khác với chỉ ước về hành động đơn thuần ('controlled'). 'Had controlled' sai vì đó là ước về quá khứ, trong khi câu đang nói về khả năng kiểm soát ngay ở hiện tại, thể hiện qua từ 'better' mang tính so sánh liên tục." },
  { id: "c176", question: "She'll be devastated _____ she finds out the truth.", options: ["when", "if", "unless", "in case"], correctIndex: 1, explanation: "Câu điều kiện loại 1: if + hiện tại đơn (finds out), + will + V (she'll be). Việc phát hiện ra sự thật là điều kiện có thể xảy ra, dẫn đến cảm giác suy sụp. 'When' khác 'if' ở chỗ 'when' ngụ ý chắc chắn sẽ xảy ra (chỉ là vấn đề thời gian), trong khi 'if' phù hợp hơn khi việc đó chỉ là một khả năng chưa chắc chắn." },
  { id: "c177", question: "If the company _____ its strategy, it might go bankrupt.", options: ["doesn't change", "didn't change", "hadn't changed", "won't change"], correctIndex: 0, explanation: "Câu điều kiện loại 1 phủ định: If + hiện tại đơn phủ định (doesn't change), + might + V. Việc công ty không thay đổi chiến lược là một khả năng thực tế trong hiện tại/tương lai, có thể dẫn đến nguy cơ phá sản. 'Didn't change' sai vì đó là quá khứ đơn (thuộc loại 2), không phù hợp với một cảnh báo mang tính thực tế, hiện tại như câu này." },
  { id: "c178", question: "I'd rather _____ the cheaper option.", options: ["choose", "chose", "to choose", "choosing"], correctIndex: 0, explanation: "Khi không có chủ ngữ thứ hai sau 'I'd rather', động từ theo sau luôn ở dạng nguyên thể không 'to' (bare infinitive) - ở đây là 'choose'. Đây là quy tắc cố định của cấu trúc 'would rather' khi chủ ngữ của cả hai mệnh đề là một. 'Chose' sai vì chỉ dùng khi có chủ ngữ thứ hai khác với người nói; 'to choose/choosing' sai vì 'rather' không bao giờ đi với to-infinitive hay V-ing." },
  { id: "c179", question: "If he _____ here now, he would be so proud of you.", options: ["is", "was", "were", "has been"], correctIndex: 2, explanation: "Câu điều kiện loại 2: If he were here now (nhưng thực tế anh ấy không có mặt), + would be (would + V). Từ 'now' xác nhận đây là giả định về hiện tại, và với to be, 'were' là hình thức chuẩn mực cho câu điều kiện loại 2, bất kể chủ ngữ số ít hay số nhiều. 'Was' vẫn nghe được trong văn nói nhưng 'were' là lựa chọn ngữ pháp chuẩn hơn." },
  { id: "c180", question: "What would you have done if you _____ been in her shoes?", options: ["have", "had", "are", "were"], correctIndex: 1, explanation: "Câu hỏi ở câu điều kiện loại 3: What would you have done if you had been...? Vế chính 'would you have done' xác nhận công thức loại 3, và vì chỗ trống đứng trước 'been' (V3 của to be), cần trợ động từ 'had' để tạo thành 'had been' (quá khứ hoàn thành). 'Were' sai vì sẽ tạo thành 'were been' - không đúng ngữ pháp, trong khi 'had been' mới là dạng quá khứ hoàn thành chuẩn." },
  { id: "c181", question: "She's treating him as if he _____ a child!", options: ["is", "was", "were", "has been"], correctIndex: 2, explanation: "'As if' + were (hình thức giả định của to be) dùng để so sánh với một thực tế không đúng - đối xử với anh ta như thể là trẻ con, nhưng thực ra không phải. Đây là quy tắc giống câu điều kiện loại 2: to be sau 'as if' luôn ưu tiên 'were' cho mọi chủ ngữ để nhấn mạnh tính phi thực tế, mang sắc thái phàn nàn/chê trách. 'Is' sai vì sẽ ngụ ý điều đó có thể đúng, làm mất đi ý nghĩa so sánh phi thực tế của câu." },
  { id: "c182", question: "If you _____ your phone, you won't be able to call for help.", options: ["lose", "lost", "will lose", "had lost"], correctIndex: 0, explanation: "Câu điều kiện loại 1: If + hiện tại đơn (lose), + won't be able to (will not). Làm mất điện thoại là một khả năng thực tế có thể xảy ra, dẫn đến hậu quả không gọi được cứu trợ. 'Will lose' sai vì mệnh đề 'if' không bao giờ dùng 'will', dù cả câu đang cảnh báo về một tình huống trong tương lai." },
  { id: "c183", question: "I wish I _____ where I left my keys.", options: ["know", "knew", "had known", "would know"], correctIndex: 1, explanation: "'Wish' + quá khứ đơn (knew) dùng để ước về một điều không biết ở hiện tại - người nói hiện không biết mình để chìa khóa ở đâu. Đây là cách dùng cơ bản nhất của 'wish': ước về một thực tế trái ngược ở hiện tại, tương tự tinh thần câu điều kiện loại 2. 'Know' (hiện tại đơn) sai vì động từ theo sau 'wish' luôn phải lùi một thì so với hiện tại thực." },
  { id: "c184", question: "If only they _____ the match — it was so close!", options: ["win", "won", "had won", "would win"], correctIndex: 2, explanation: "'If only' + quá khứ hoàn thành (had won) dùng để tiếc nuối về một kết quả đã xảy ra trong quá khứ - trận đấu đã thua dù rất sít sao ('it was so close'). Cụm 'was' (quá khứ) xác nhận trận đấu đã kết thúc, nên cần quá khứ hoàn thành để nói về điều ước ngược lại kết quả đó. 'Won' (quá khứ đơn) sai vì chỉ dùng cho ước về hiện tại, không phù hợp khi rõ ràng đang tiếc nuối về một sự việc đã hoàn toàn kết thúc." },
  { id: "c185", question: "_____ the situation change, we'll adapt our plans accordingly.", options: ["If", "Should", "Were", "Had"], correctIndex: 1, explanation: "Đảo ngữ trang trọng của câu điều kiện loại 1: 'Should the situation change' = 'If the situation should change' (nếu như tình hình thay đổi). Cách nói này phổ biến trong văn bản kinh doanh/kế hoạch để diễn tả một khả năng chưa chắc chắn trong tương lai một cách lịch sự, chuyên nghiệp. 'Were' và 'Had' là đảo ngữ của loại 2, loại 3, không khớp với vế chính 'we'll adapt' (will - loại 1)." },
  { id: "c186", question: "If he worked out more, he _____ look healthier.", options: ["will", "would", "could", "should"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (worked out), + would + V (would look). Thực tế anh ấy không tập luyện nhiều nên chưa trông khỏe mạnh hơn - một giả định trái thực tế ở hiện tại. 'Will' sai vì không khớp thì với 'worked out' (quá khứ đơn) ở mệnh đề 'if' - will chỉ đi cùng if + hiện tại đơn của loại 1." },
  { id: "c187", question: "She _____ have become a doctor if she hadn't been afraid of hospitals.", options: ["might", "will", "has", "is"], correctIndex: 0, explanation: "Câu điều kiện loại 3: mệnh đề 'if' đã chia 'hadn't been' (quá khứ hoàn thành phủ định) nên vế chính cần 'might have + V3' (might have become) để diễn tả một khả năng đã có thể xảy ra nhưng đã không xảy ra vì nỗi sợ bệnh viện. 'Will' hoàn toàn sai vì không bao giờ xuất hiện trong công thức câu điều kiện loại 3, chỉ các động từ khiếm khuyết dạng quá khứ (might/would/could) + have mới đúng." },
  { id: "c188", question: "If you _____ a time machine, where would you go?", options: ["have", "had", "will have", "would have"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (had), + where would you go? Có một cỗ máy thời gian là một giả định hoàn toàn viễn tưởng, không có thật, nên mệnh đề 'if' chia quá khứ đơn 'had'. 'Will have' sai vì đây không phải một khả năng thực tế trong tương lai (loại 1) mà là một giả định phi thực tế cần công thức loại 2." },
  { id: "c189", question: "It's time this problem _____ seriously.", options: ["takes", "took", "was taken", "is taken"], correctIndex: 2, explanation: "'It's time' + quá khứ đơn bị động (was taken) diễn tả điều đáng lẽ đã phải được xử lý rồi - vấn đề này lẽ ra đã phải được giải quyết nghiêm túc từ trước. Vì chủ thể thực hiện hành động không được nêu rõ (ai đó nên giải quyết vấn đề), câu chuyển sang thể bị động nhưng vẫn giữ nguyên tắc chia quá khứ đơn của cấu trúc 'it's time'. 'Is taken' (hiện tại đơn bị động) sai vì cấu trúc 'it's time' luôn đòi hỏi dạng quá khứ đơn giả định, không dùng hiện tại đơn." },
  { id: "c190", question: "She'd rather _____ work from home than commute every day.", options: ["be", "been", "to be", "being"], correctIndex: 0, explanation: "Khi 'I/she'd rather' không có chủ ngữ thứ hai, động từ theo sau dùng nguyên thể không 'to' (bare infinitive) - ở đây là 'be' (trong cụm 'be able to work' được rút gọn ý). Đây là quy tắc cố định: cùng một chủ ngữ thì dùng nguyên mẫu không 'to', khác chủ ngữ mới chia quá khứ đơn. 'Been/to be/being' đều sai vì không phải dạng nguyên thể không 'to' mà cấu trúc 'would rather' yêu cầu." },
  { id: "c191", question: "Unless they _____ the deadline, there will be penalties.", options: ["meet", "met", "will meet", "would meet"], correctIndex: 0, explanation: "'Unless' + hiện tại đơn (meet) là câu điều kiện loại 1: unless they meet the deadline = if they don't meet the deadline. Đáp ứng thời hạn là một khả năng thực tế, và vế chính 'there will be penalties' xác nhận công thức loại 1. 'Will meet' sai vì phần sau 'unless' không bao giờ dùng 'will', giống mọi mệnh đề điều kiện khác." },
  { id: "c192", question: "If he _____ his glasses, he wouldn't be able to read.", options: ["loses", "lost", "had lost", "would lose"], correctIndex: 1, explanation: "Câu điều kiện loại 2: If + quá khứ đơn (lost), + wouldn't be able to (would not). Đây là một giả định giả thuyết - nếu anh ấy làm mất kính (một tình huống được đặt ra để bàn luận, không nhất thiết đang xảy ra), thì sẽ không đọc được. 'Loses' (hiện tại đơn) sai vì không khớp thì với 'wouldn't' ở vế chính - would luôn đòi hỏi mệnh đề 'if' ở quá khứ đơn." },
  { id: "c193", question: "I wish I _____ gone to the party — it sounded fun.", options: ["have", "had", "would have", "could"], correctIndex: 1, explanation: "'Wish' + quá khứ hoàn thành (had gone) dùng để hối tiếc về một việc đã không làm trong quá khứ - đã không đi dự tiệc dù nghe có vẻ vui. Vế sau 'it sounded fun' (quá khứ) xác nhận đây là chuyện đã qua nên cần quá khứ hoàn thành. 'Would have' sai vì sau 'wish', ta dùng 'had + V3' để hối tiếc quá khứ, không dùng 'would have' (đó là công thức cho mệnh đề kết quả trong câu điều kiện loại 3, không phải sau 'wish')." },
  { id: "c194", question: "If you _____ a cold, stay at home and rest.", options: ["catch", "caught", "will catch", "had caught"], correctIndex: 0, explanation: "Câu điều kiện loại 1 dạng lời khuyên: If + hiện tại đơn (catch), + imperative (stay at home). Bị cảm lạnh là một khả năng thực tế có thể xảy ra, và lời khuyên được đưa ra bằng câu mệnh lệnh thay vì 'will'. 'Caught' sai vì đó là quá khứ đơn (thuộc loại 2), không phù hợp với một lời khuyên mang tính thực tế, áp dụng ngay như câu này." },
  { id: "c195", question: "She _____ in touch if she had your contact information.", options: ["will get", "would get", "gets", "got"], correctIndex: 1, explanation: "Câu điều kiện loại 2: mệnh đề 'if' đã chia 'had' (quá khứ đơn) nên vế chính phải dùng 'would get' để tương ứng - cô ấy hiện không có thông tin liên hệ của bạn nên sẽ không thể liên lạc. 'Will get' sai vì không khớp thì với 'had' ở mệnh đề 'if' - will chỉ đi cùng if + hiện tại đơn của loại 1, không phải quá khứ đơn." },
  { id: "c196", question: "If only the weather _____ a bit warmer — I'd love to go swimming.", options: ["is", "was", "were", "had been"], correctIndex: 2, explanation: "'If only' + were dùng để ước về thời tiết hiện tại không như mong muốn - trời hiện không đủ ấm để đi bơi. Với to be, 'were' là hình thức giả định chuẩn mực cho mọi chủ ngữ trong cấu trúc ước muốn kiểu câu điều kiện loại 2. 'Had been' sai vì đó là ước về quá khứ, trong khi vế sau 'I'd love to go swimming' (would love - hiện tại) xác nhận đây là ước muốn về thời tiết ngay bây giờ." },
  { id: "c197", question: "The accident _____ have been avoided if the driver had been more alert.", options: ["can", "could", "may", "will"], correctIndex: 1, explanation: "Câu điều kiện loại 3 ở thể bị động: mệnh đề 'if' đã chia 'had been' (quá khứ hoàn thành) nên vế chính cần 'could have been avoided' (could have + V3 bị động) để diễn tả một khả năng đã có thể xảy ra nhưng đã không xảy ra. Tài xế đã không đủ tỉnh táo nên tai nạn đã xảy ra. 'Will' hoàn toàn sai vì không bao giờ xuất hiện trong công thức câu điều kiện loại 3." },
  { id: "c198", question: "I'd rather you _____ quiet while I'm thinking.", options: ["keep", "kept", "will keep", "would keep"], correctIndex: 1, explanation: "Cấu trúc 'I'd rather + chủ ngữ khác + quá khứ đơn' (kept) dùng để yêu cầu người khác làm gì đó ở hiện tại - muốn người nghe giữ yên lặng trong khi mình đang suy nghĩ. 'Keep' (hiện tại đơn) sai vì khi có chủ ngữ thứ hai theo sau 'I'd rather', động từ luôn phải chia ở quá khứ đơn giả định, dù ý nghĩa là ở hiện tại." },
  { id: "c199", question: "Unless something _____ soon, I'm going to lose patience.", options: ["changes", "changed", "will change", "would change"], correctIndex: 0, explanation: "'Unless' + hiện tại đơn (changes) là câu điều kiện loại 1: unless something changes = if nothing changes. Vì chủ ngữ 'something' là số ít nên động từ phải thêm 's'. 'Will change' sai vì phần sau 'unless' không bao giờ dùng 'will', giống mọi mệnh đề bắt đầu bằng liên từ điều kiện khác." },
  { id: "c200", question: "If he _____ the application form correctly, he would have gotten the job.", options: ["fills", "filled", "had filled", "would fill"], correctIndex: 2, explanation: "Câu điều kiện loại 3: If + had filled (quá khứ hoàn thành), + would have + V3 (would have gotten). Việc điền đơn không chính xác đã xảy ra trong quá khứ nên anh ấy đã không được nhận việc - một cơ hội đã bị bỏ lỡ hoàn toàn. 'Filled' (quá khứ đơn) sai vì vế chính 'would have gotten' (loại 3) đòi hỏi mệnh đề 'if' phải ở quá khứ hoàn thành, không phải quá khứ đơn của loại 2." },
];
